const REZEPTE = [
{"n": "Apfel-Crumble", "von": 9, "bis": 12, "z": 50, "k": "v", "zu": [[5, "", "Äpfel, säuerlich"], [100, "g", "Mehl"], [80, "g", "Butter, kalt"], [70, "g", "Zucker"], [50, "g", "Haferflocken"], [2, "dl", "Vanillesauce"]], "vo": ["Zimt", "Zitronensaft"], "s": ["Ofen auf 190 °C vorheizen.", "Äpfel schälen, entkernen, in Würfel schneiden und mit Zimt und Zitronensaft in eine Gratinform geben.", "Mehl, Zucker, Haferflocken und kalte Butter mit den Fingern zu Streuseln verreiben.", "Streusel über die Äpfel verteilen und 30 Min backen, bis sie goldbraun sind.", "Warm mit Vanillesauce servieren."]},
{"n": "Aprikosenwähe", "von": 6, "bis": 8, "z": 60, "k": "v", "zu": [[1, "Packung", "Kuchenteig, rund"], [800, "g", "Aprikosen"], [3, "EL", "Gemahlene Mandeln"], [2, "", "Eier"], [1.5, "dl", "Rahm"], [60, "g", "Zucker"], [1, "Packung", "Vanillezucker"]], "vo": ["Mehl"], "s": ["Teig mit dem Papier in ein Wähenblech legen und den Boden mit einer Gabel einstechen.", "Mandeln auf dem Boden verteilen.", "Aprikosen halbieren, entsteinen und mit der Schnittfläche nach oben dicht darauflegen.", "Eier, Rahm, Zucker, Vanillezucker und wenig Mehl zu einem Guss verrühren und darübergiessen.", "Auf der untersten Rille bei 220 °C 35 Min backen und lauwarm servieren."]},
{"n": "Basler Mehlsuppe", "von": 1, "bis": 3, "z": 60, "k": "v", "zu": [[1, "", "Zwiebel"], [80, "g", "Mehl"], [1.5, "l", "Rindsbouillon oder Gemüsebouillon"], [1, "dl", "Rotwein"], [100, "g", "Sbrinz, gerieben"], [1, "", "Ruchbrot"]], "vo": ["Butter", "Salz", "Pfeffer", "Muskat"], "s": ["Mehl in einer trockenen Pfanne unter ständigem Rühren haselnussbraun rösten, auskühlen lassen.", "Zwiebel fein hacken und in Butter andünsten, geröstetes Mehl dazugeben.", "Nach und nach unter Rühren mit kalter Bouillon und Rotwein ablöschen.", "Zugedeckt mindestens 45 Min köcheln, ab und zu rühren.", "Mit Muskat und Pfeffer abschmecken, mit Käse bestreuen und mit Brot servieren."]},
{"n": "Beeren-Tiramisu", "von": 6, "bis": 8, "z": 30, "k": "v", "zu": [[500, "g", "Gemischte Beeren"], [250, "g", "Mascarpone"], [250, "g", "Quark"], [1, "Packung", "Löffelbiskuits"], [2, "dl", "Orangensaft"], [60, "g", "Zucker"], [1, "", "Zitrone, unbehandelt"]], "vo": [], "s": ["Einen Teil der Beeren mit etwas Zucker pürieren, restliche Beeren beiseitestellen.", "Mascarpone, Quark, Zucker und Zitronenschale glatt rühren.", "Löffelbiskuits kurz in Orangensaft tauchen und eine Form damit auslegen.", "Abwechselnd Creme, Beerenpüree und Beeren einschichten, mit Creme abschliessen.", "Mindestens 3 Std kühl stellen und vor dem Servieren mit Beeren garnieren."]},
{"n": "Bratwurst mit Apfel-Rotkraut", "von": 10, "bis": 2, "z": 60, "k": "f", "zu": [[3, "", "Kalbsbratwürste"], [600, "g", "Rotkraut"], [2, "", "Äpfel"], [1, "", "Zwiebel"], [1, "dl", "Rotwein"], [700, "g", "Kartoffeln, festkochend"]], "vo": ["Rapsöl", "Butter", "Essig", "Zucker", "Zimt", "Gewürze (Lorbeer, Nelken)", "Salz", "Pfeffer"], "s": ["Rotkraut fein hobeln, Zwiebel und Äpfel in Würfel schneiden.", "Zwiebel in Butter andünsten, Rotkraut und Äpfel dazugeben. Mit Rotwein, Essig, Zucker und Gewürzen 40 Min zugedeckt schmoren.", "Kartoffeln schälen und in Salzwasser 20 Min kochen, dann in Butter schwenken.", "Bratwürste in Öl bei mittlerer Hitze rundum 12 Min braten.", "Rotkraut abschmecken und mit Bratwurst und Kartoffeln servieren."]},
{"n": "Bratwurst mit Kartoffelsalat", "von": 6, "bis": 8, "z": 45, "k": "f", "zu": [[3, "", "Kalbsbratwürste"], [900, "g", "Kartoffeln, festkochend"], [1, "", "Zwiebel"], [1, "Bund", "Schnittlauch"], [1, "", "Gurke"], [3, "", "Essiggurken"]], "vo": ["Gemüsebouillon", "Essig", "Senf", "Rapsöl", "Salz", "Pfeffer"], "s": ["Kartoffeln in der Schale weich kochen, schälen und noch warm in Scheiben schneiden.", "Zwiebel fein hacken, mit heisser Bouillon, Essig, Senf und Öl verrühren und über die Kartoffeln giessen.", "Gurke und Essiggurken in feine Scheiben schneiden und unterheben, 20 Min ziehen lassen.", "Bratwürste auf dem Grill oder in der Pfanne rundum 10 Min braten.", "Salat mit Schnittlauch bestreuen und mit den Würsten und Senf servieren."]},
{"n": "Bärlauch-Spätzli mit Bergkäse", "von": 3, "bis": 4, "z": 40, "k": "v", "zu": [[350, "g", "Knöpflimehl"], [4, "", "Eier"], [1.5, "dl", "Milch"], [1, "Bund", "Bärlauch"], [120, "g", "Bergkäse, gerieben"], [1, "", "Zwiebel"]], "vo": ["Salz", "Muskat", "Butter", "Pfeffer"], "s": ["Bärlauch mit der Milch fein pürieren.", "Mehl, Eier, Bärlauchmilch, Salz und Muskat zu einem zähen Teig klopfen, 15 Min ruhen lassen.", "Teig portionenweise ins siedende Salzwasser streichen. Spätzli abschöpfen, sobald sie aufschwimmen.", "Zwiebel in Ringe schneiden und in Butter goldbraun braten.", "Spätzli in Butter schwenken, mit Käse mischen und mit Zwiebeln servieren."]},
{"n": "Bärlauchrisotto", "von": 3, "bis": 4, "z": 35, "k": "v", "zu": [[240, "g", "Risottoreis"], [1, "", "Zwiebel"], [1, "dl", "Weisswein"], [1, "Bund", "Bärlauch"], [60, "g", "Parmesan"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer", "Olivenöl"], "s": ["Zwiebel fein hacken und in Butter andünsten. Reis zugeben und 2 Min mitdünsten.", "Mit Wein ablöschen. Nach und nach heisse Bouillon zugeben und unter Rühren 18 Min köcheln.", "Bärlauch waschen, mit etwas Olivenöl fein pürieren.", "Bärlauch, Parmesan und ein Stück Butter unter den Risotto ziehen.", "Mit Salz und Pfeffer abschmecken und sofort servieren."]},
{"n": "Bündner Gerstensuppe", "von": 11, "bis": 3, "z": 90, "k": "f", "zu": [[120, "g", "Rollgerste"], [150, "g", "Bündner Rohschinken oder Speck, gewürfelt"], [1, "", "Lauch"], [2, "", "Rüebli"], [0.25, "", "Knollensellerie"], [1, "", "Zwiebel"], [1, "dl", "Rahm"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Gerste über Nacht oder mindestens 1 Std einweichen, abspülen.", "Gemüse und Zwiebel in kleine Würfel schneiden.", "Speck und Zwiebel in Butter andünsten, Gemüse und Gerste dazugeben.", "Mit Bouillon auffüllen und zugedeckt 60 Min köcheln.", "Rahm einrühren und mit Salz und Pfeffer abschmecken."]},
{"n": "Capuns", "von": 8, "bis": 11, "z": 90, "k": "f", "zu": [[250, "g", "Mehl"], [3, "", "Eier"], [2, "dl", "Milch"], [100, "g", "Salsiz"], [50, "g", "Bündnerfleisch"], [18, "", "Mangoldblätter, gross"], [2, "dl", "Rahm"], [80, "g", "Bergkäse"], [1, "Bund", "Schnittlauch"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer", "Muskat"], "s": ["Mehl, Eier, die Hälfte der Milch und Salz zu einem zähen Spätzliteig klopfen und 20 Min ruhen lassen.", "Salsiz und Bündnerfleisch fein würfeln, die Hälfte des Schnittlauchs hacken und alles unter den Teig mischen.", "Mangoldblätter kurz blanchieren, je einen Löffel Teig daraufgeben und satt einrollen.", "Capuns in eine gebutterte Gratinform legen. Restliche Milch, Rahm und etwas Bouillon darübergiessen.", "Zugedeckt bei 180 °C 30 Min im Ofen garen, dann geriebenen Käse darüberstreuen und 10 Min gratinieren.", "Mit restlichem Schnittlauch bestreut servieren."]},
{"n": "Chicorée mit Schinken überbacken", "von": 12, "bis": 3, "z": 50, "k": "f", "zu": [[6, "", "Chicorée"], [6, "", "Tranchen Schinken"], [5, "dl", "Milch"], [100, "g", "Greyerzer, gerieben"], [600, "g", "Kartoffeln, festkochend"]], "vo": ["Butter", "Mehl", "Zucker", "Muskat", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen. Chicorée halbieren und in Salzwasser mit wenig Zucker 8 Min kochen, gut abtropfen.", "Kartoffeln in Salzwasser 20 Min kochen.", "Butter schmelzen, Mehl anschwitzen, Milch einrühren und 5 Min köcheln, mit Muskat würzen und die Hälfte des Käses unterrühren.", "Chicoréehälften paarweise in Schinken wickeln und in eine Gratinform legen.", "Sauce darübergiessen, restlichen Käse darüberstreuen und 20 Min überbacken, mit den Kartoffeln servieren."]},
{"n": "Chicorée-Orangen-Salat", "von": 12, "bis": 3, "z": 20, "k": "v", "zu": [[3, "", "Chicorée"], [3, "", "Orangen"], [60, "g", "Baumnüsse"], [150, "g", "Ziegenfrischkäse"], [1, "", "Baguette"]], "vo": ["Olivenöl", "Essig", "Honig", "Senf", "Salz", "Pfeffer"], "s": ["Baumnüsse ohne Fett in einer Pfanne rösten.", "Orangen schälen, Filets herausschneiden und den Saft auffangen.", "Orangensaft mit Essig, Senf, Honig und Öl zu einer Sauce verrühren.", "Chicorée in Blätter zerteilen, mit Orangenfilets anrichten.", "Sauce darüberträufeln, Ziegenkäse darüberbröckeln, Nüsse darüberstreuen und mit Brot servieren."]},
{"n": "Chili con carne", "von": 1, "bis": 12, "z": 60, "k": "f", "zu": [[400, "g", "Hackfleisch, Rind"], [1, "", "Zwiebel"], [1, "", "Peperoni, rot"], [1, "Dose", "Kidneybohnen"], [1, "Dose", "Mais"], [2, "Dose", "Pelati"], [240, "g", "Langkornreis"], [1, "Becher", "Sauerrahm"]], "vo": ["Rapsöl", "Knoblauch", "Kreuzkümmel", "Paprika", "Chili", "Oregano", "Tomatenpüree", "Salz"], "s": ["Zwiebel, Peperoni und Knoblauch hacken und in Öl andünsten.", "Hackfleisch dazugeben und krümelig braten. Gewürze und Tomatenpüree kurz mitrösten.", "Pelati dazugeben und 30 Min köcheln.", "Bohnen und Mais abspülen, dazugeben und 10 Min mitköcheln.", "Reis kochen. Chili abschmecken und mit Reis und Sauerrahm servieren."]},
{"n": "Chili sin carne", "von": 1, "bis": 12, "z": 45, "k": "vg", "zu": [[2, "Dose", "Kidneybohnen"], [1, "Dose", "Mais"], [2, "Dose", "Tomaten, gehackt (400 g)"], [2, "", "Peperoni, rot"], [1, "", "Zwiebel"], [200, "g", "Langkornreis"]], "vo": ["Olivenöl", "Knoblauch", "Kreuzkümmel", "Paprika", "Chili", "Tomatenpüree", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Zwiebel, Knoblauch und Peperoni würfeln und in Olivenöl andünsten.", "Tomatenpüree und Gewürze kurz mitrösten.", "Tomaten, abgespülte Bohnen und Mais zugeben und 25 Min köcheln.", "Mit Salz abschmecken und mit Reis servieren."]},
{"n": "Choucroute de la mer", "von": 11, "bis": 2, "z": 60, "k": "fi", "zu": [[600, "g", "Sauerkraut, roh"], [300, "g", "Lachsfilet"], [300, "g", "Kabeljaufilet"], [1, "", "Zwiebel"], [2, "dl", "Weisswein"], [1.5, "dl", "Rahm"], [600, "g", "Kartoffeln, festkochend"]], "vo": ["Butter", "Gemüsebouillon", "Wacholder", "Salz", "Pfeffer"], "s": ["Zwiebel in Streifen schneiden und in Butter andünsten, Sauerkraut und Wacholder dazugeben.", "Mit Wein und wenig Bouillon ablöschen und zugedeckt 35 Min köcheln.", "Kartoffeln schälen und in Salzwasser 20 Min kochen.", "Fisch in Stücke schneiden, salzen und auf das Sauerkraut legen, zugedeckt 8 Min ziehen lassen.", "Fisch herausnehmen, Rahm unter das Sauerkraut mischen und alles mit den Kartoffeln anrichten."]},
{"n": "Chriesiprägel (Kirschenauflauf)", "von": 6, "bis": 7, "z": 60, "k": "v", "zu": [[600, "g", "Kirschen"], [4, "", "Weggli vom Vortag"], [3, "dl", "Milch"], [3, "", "Eier"], [80, "g", "Zucker"], [60, "g", "Gemahlene Mandeln"], [50, "g", "Butter"]], "vo": ["Zimt"], "s": ["Weggli in Würfel schneiden, mit warmer Milch übergiessen und 10 Min einweichen.", "Kirschen entsteinen.", "Butter schmelzen und mit Eiern, Zucker, Mandeln und Zimt verrühren, unter die Brotmasse mischen.", "Kirschen unterheben und alles in eine gebutterte Form füllen.", "Bei 180 °C 40 Min backen und lauwarm servieren."]},
{"n": "Coq au vin", "von": 9, "bis": 12, "z": 120, "k": "f", "zu": [[1.2, "kg", "Pouletteile mit Knochen"], [100, "g", "Speckwürfeli"], [200, "g", "Champignons"], [200, "g", "Perlzwiebeln"], [2, "", "Rüebli"], [5, "dl", "Rotwein"], [1, "", "Baguette"]], "vo": ["Rapsöl", "Butter", "Mehl", "Knoblauch", "Tomatenpüree", "Gewürze (Lorbeer, Thymian)", "Salz", "Pfeffer"], "s": ["Pouletteile würzen, mit Mehl bestäuben und in Öl rundum goldbraun anbraten. Herausnehmen.", "Speck, Perlzwiebeln und Rüebli im Bratfett anrösten, Knoblauch und Tomatenpüree kurz mitrösten.", "Mit Rotwein ablöschen, Poulet und Gewürze dazugeben und zugedeckt 1 Std schmoren.", "Champignons vierteln, in Butter anbraten und die letzten 15 Min mitschmoren.", "Sauce abschmecken und mit Baguette servieren."]},
{"n": "Couscous-Salat mit Radiesli", "von": 4, "bis": 6, "z": 25, "k": "vg", "zu": [[250, "g", "Couscous"], [1, "Bund", "Radiesli"], [1, "", "Gurke"], [1, "Dose", "Kichererbsen"], [1, "Bund", "Peterli"], [0.5, "Bund", "Minze"], [1, "", "Zitrone"]], "vo": ["Olivenöl", "Kreuzkümmel", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Couscous mit heisser Bouillon übergiessen und zugedeckt 10 Min quellen lassen.", "Radiesli vierteln, Gurke würfeln, Kichererbsen abspülen.", "Kräuter fein hacken.", "Zitronensaft mit Olivenöl, Kreuzkümmel, Salz und Pfeffer verrühren.", "Couscous mit einer Gabel auflockern und mit Gemüse, Kräutern und Sauce mischen."]},
{"n": "Crevetten-Curry mit Kokos", "von": 1, "bis": 12, "z": 30, "k": "fi", "zu": [[400, "g", "Crevetten, roh, geschält"], [1, "", "Zwiebel"], [1, "", "Peperoni, rot"], [1, "Dose", "Kokosmilch"], [1, "Dose", "Tomaten, gehackt"], [20, "g", "Ingwer"], [240, "g", "Basmatireis"], [1, "", "Limette"], [0.5, "Bund", "Koriander"]], "vo": ["Rapsöl", "Curry", "Kurkuma", "Salz", "Knoblauch"], "s": ["Reis nach Packungsangabe garen.", "Zwiebel, Knoblauch und Ingwer hacken, Peperoni in Streifen schneiden und alles in Öl andünsten.", "Curry und Kurkuma kurz mitrösten, Kokosmilch und Tomaten dazugeben und 10 Min köcheln.", "Crevetten dazugeben und 3–4 Min ziehen lassen, bis sie rosa sind.", "Mit Limettensaft und Salz abschmecken und mit Koriander und Reis servieren."]},
{"n": "Crevetten-Lauch-Pasta", "von": 9, "bis": 3, "z": 25, "k": "fi", "zu": [[350, "g", "Linguine"], [300, "g", "Crevetten, roh, geschält"], [2, "", "Lauch"], [1, "dl", "Weisswein"], [1, "dl", "Halbrahm"], [1, "", "Zitrone, unbehandelt"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Pasta in Salzwasser al dente kochen.", "Lauch in feine Ringe schneiden und mit Knoblauch in Öl weich dünsten.", "Mit Wein ablöschen, Halbrahm dazugeben und kurz einkochen.", "Crevetten mit Chili in einer heissen Pfanne 2 Min braten.", "Pasta, Crevetten und Lauchsauce mischen, mit Zitronenschale und -saft abschmecken."]},
{"n": "Dorade vom Grill mit Zitrone", "von": 6, "bis": 9, "z": 45, "k": "fi", "zu": [[3, "", "Doraden, küchenfertig"], [2, "", "Zitronen"], [1, "Bund", "Peterli"], [600, "g", "Frühkartoffeln"], [2, "", "Zucchetti"], [250, "g", "Cherrytomaten"]], "vo": ["Olivenöl", "Rosmarin", "Thymian", "Salz", "Pfeffer", "Knoblauch"], "s": ["Kartoffeln halbieren, mit Olivenöl und Rosmarin mischen und bei 200 °C 30 Min im Ofen rösten.", "Doraden innen und aussen salzen, mit Zitronenscheiben, Peterli, Thymian und Knoblauch füllen.", "Fische mit Olivenöl bestreichen und auf dem Grill oder im Fischgitter je Seite 7–8 Min grillieren.", "Zucchetti in Scheiben schneiden und mit den Tomaten kurz mitgrillieren.", "Fisch mit Gemüse, Kartoffeln und Zitronenschnitzen servieren."]},
{"n": "Dreikönigskuchen", "von": 12, "bis": 1, "z": 150, "k": "v", "zu": [[500, "g", "Weissmehl"], [1, "Packung", "Hefe, frisch"], [2.5, "dl", "Milch"], [60, "g", "Zucker"], [80, "g", "Butter, weich"], [1, "", "Ei"], [80, "g", "Sultaninen"], [1, "", "Zitrone, unbehandelt"], [2, "EL", "Hagelzucker"]], "vo": ["Salz"], "s": ["Hefe in lauwarmer Milch auflösen, mit Mehl, Zucker, Salz, Butter und abgeriebener Zitronenschale zu einem glatten Teig kneten.", "Sultaninen einarbeiten und den Teig zugedeckt 1 Std aufs Doppelte gehen lassen.", "Teig in eine grosse und mehrere kleine Kugeln teilen, in eine Kugel eine Mandel oder Königsfigur stecken.", "Grosse Kugel in die Mitte eines Blechs legen, kleine rundherum anordnen, 30 Min gehen lassen.", "Mit verquirltem Ei bestreichen, mit Hagelzucker bestreuen und bei 180 °C 30 Min backen."]},
{"n": "Eglifilets mit Kräutern", "von": 4, "bis": 6, "z": 30, "k": "fi", "zu": [[450, "g", "Eglifilets"], [800, "g", "Kartoffeln, neue"], [1, "Bund", "Peterli"], [0.5, "Bund", "Schnittlauch"], [1, "", "Zitrone"], [60, "g", "Butter"]], "vo": ["Mehl", "Salz", "Pfeffer"], "s": ["Kartoffeln in Salzwasser 20 Min weich kochen.", "Kräuter fein hacken.", "Filets salzen und pfeffern und leicht mit Mehl bestäuben.", "In Butter pro Seite 1–2 Min goldbraun braten.", "Kräuter in die heisse Butter geben, mit Zitronensaft abschmecken und über die Filets giessen. Mit Kartoffeln servieren."]},
{"n": "Eglifilets mit Sommergemüse", "von": 6, "bis": 9, "z": 30, "k": "fi", "zu": [[450, "g", "Eglifilets"], [2, "", "Zucchetti"], [1, "", "Peperoni, gelb"], [250, "g", "Cherrytomaten"], [600, "g", "Frühkartoffeln"], [1, "", "Zitrone"], [0.5, "Bund", "Peterli"]], "vo": ["Butter", "Olivenöl", "Mehl", "Salz", "Pfeffer"], "s": ["Kartoffeln in Salzwasser 20 Min kochen.", "Zucchetti und Peperoni würfeln, in Olivenöl 5 Min braten, Tomaten kurz mitbraten und würzen.", "Eglifilets salzen, leicht mit Mehl bestäuben und in Butter je Seite 1–2 Min braten.", "Mit Zitronensaft beträufeln und mit Peterli bestreuen.", "Fisch mit Gemüse und Kartoffeln servieren."]},
{"n": "Erbsensuppe mit Minze", "von": 5, "bis": 6, "z": 25, "k": "vg", "zu": [[600, "g", "Erbsen, frisch oder tiefgekühlt"], [1, "", "Zwiebel"], [1, "", "Kartoffel, mehligkochend"], [0.5, "Bund", "Minze"], [3, "", "Scheiben Ruchbrot"]], "vo": ["Olivenöl", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Zwiebel und Kartoffel klein würfeln und in Olivenöl andünsten.", "Mit Bouillon ablöschen und 10 Min köcheln.", "Erbsen zugeben und 5 Min mitkochen.", "Minzblätter zugeben, alles fein pürieren und abschmecken.", "Brot in Würfel schneiden, in Olivenöl knusprig rösten und über die Suppe streuen."]},
{"n": "Erdbeer-Rhabarber-Crumble", "von": 5, "bis": 6, "z": 50, "k": "v", "zu": [[400, "g", "Rhabarber"], [300, "g", "Erdbeeren"], [100, "g", "Mehl"], [80, "g", "Butter, kalt"], [100, "g", "Zucker"], [50, "g", "Haferflocken"], [1, "Packung", "Vanillezucker"]], "vo": ["Zimt"], "s": ["Ofen auf 200 °C vorheizen.", "Rhabarber in Stücke schneiden, Erdbeeren halbieren, mit einem Teil des Zuckers und Vanillezucker in eine Form geben.", "Mehl, Haferflocken, restlichen Zucker, Zimt und Butterstücke zu Streuseln verreiben.", "Streusel über den Früchten verteilen.", "30 Min backen, bis die Streusel goldbraun sind. Lauwarm servieren."]},
{"n": "Federkohl-Pasta mit Baumnüssen", "von": 10, "bis": 2, "z": 25, "k": "v", "zu": [[350, "g", "Orecchiette"], [300, "g", "Federkohl"], [60, "g", "Baumnüsse"], [60, "g", "Parmesan"], [1, "", "Zitrone, unbehandelt"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Federkohl von den Stielen zupfen und grob schneiden.", "Pasta in Salzwasser kochen, Federkohl die letzten 4 Min mitkochen. Etwas Kochwasser beiseitestellen und abgiessen.", "Baumnüsse hacken und ohne Fett rösten.", "Knoblauch und Chili in Olivenöl sanft andünsten.", "Pasta und Federkohl darin schwenken, mit etwas Kochwasser, Zitronenschale und -saft und Parmesan mischen. Mit Nüssen servieren."]},
{"n": "Fenchel-Kartoffel-Gratin", "von": 9, "bis": 11, "z": 70, "k": "v", "zu": [[600, "g", "Kartoffeln, festkochend"], [2, "", "Fenchel"], [2.5, "dl", "Rahm"], [1, "dl", "Milch"], [100, "g", "Gruyère"], [150, "g", "Blattsalat"]], "vo": ["Butter", "Knoblauch", "Muskat", "Salz", "Pfeffer", "Essig", "Olivenöl"], "s": ["Ofen auf 200 °C vorheizen, eine Gratinform mit Butter und Knoblauch ausreiben.", "Kartoffeln schälen und in dünne Scheiben hobeln, Fenchel in feine Streifen schneiden.", "Beides abwechselnd in die Form schichten und jede Lage würzen.", "Rahm und Milch mischen, mit Muskat würzen und darübergiessen. Geriebenen Käse darüberstreuen.", "Im Ofen 50 Min backen, bis die Kartoffeln weich sind, und mit Salat servieren."]},
{"n": "Fisch-Tacos mit Mango-Salsa", "von": 6, "bis": 9, "z": 35, "k": "fi", "zu": [[450, "g", "Weisses Fischfilet (z. B. Kabeljau)"], [9, "", "Tortillas, klein"], [1, "", "Mango"], [1, "", "Avocado"], [0.25, "", "Rotkabis, klein"], [2, "", "Limetten"], [1, "Bund", "Koriander"], [1, "Becher", "Sauerrahm"]], "vo": ["Rapsöl", "Paprika", "Kreuzkümmel", "Chili", "Salz", "Mehl"], "s": ["Mango und Avocado würfeln, mit Limettensaft, Koriander, Chili und Salz zu einer Salsa mischen.", "Rotkabis fein hobeln und mit Limettensaft und Salz anmachen.", "Fisch in Streifen schneiden, mit Gewürzen und wenig Mehl bestäuben und in Öl 2–3 Min pro Seite braten.", "Tortillas in einer trockenen Pfanne kurz erwärmen.", "Tortillas mit Kabis, Fisch, Salsa und Sauerrahm füllen."]},
{"n": "Fischcurry mit Kefen", "von": 5, "bis": 7, "z": 30, "k": "fi", "zu": [[450, "g", "Kabeljaufilet"], [1, "Dose", "Kokosmilch"], [2, "EL", "Gelbe Currypaste"], [250, "g", "Kefen"], [1, "Bund", "Frühlingszwiebeln"], [240, "g", "Jasminreis"], [1, "", "Limette"], [2, "EL", "Fischsauce"]], "vo": ["Rapsöl", "Zucker"], "s": ["Reis nach Packungsangabe kochen.", "Fisch in grosse Würfel schneiden, Frühlingszwiebeln in Ringe.", "Currypaste im Öl kurz anrösten, Kokosmilch zugeben und aufkochen.", "Kefen und Fisch zugeben und 5 Min sanft köcheln, nicht mehr rühren.", "Mit Fischsauce, Zucker und Limettensaft abschmecken, Frühlingszwiebeln darüber und mit Reis servieren."]},
{"n": "Fischsuppe mit Safran", "von": 11, "bis": 3, "z": 50, "k": "fi", "zu": [[500, "g", "Weisses Fischfilet (z.B. Kabeljau)"], [150, "g", "Crevetten, roh, geschält"], [1, "", "Fenchel"], [1, "", "Lauch"], [1, "", "Zwiebel"], [1, "Dose", "Pelati"], [2, "dl", "Weisswein"], [1, "", "Baguette"]], "vo": ["Olivenöl", "Knoblauch", "Safran", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Fenchel, Lauch und Zwiebel klein schneiden, mit Knoblauch in Olivenöl andünsten.", "Mit Wein ablöschen, Pelati, Safran und Bouillon dazugeben und 20 Min köcheln.", "Fisch in grosse Würfel schneiden.", "Fisch und Crevetten in die Suppe geben und 5 Min ziehen lassen, nicht mehr kochen.", "Abschmecken und mit geröstetem Baguette servieren."]},
{"n": "Flammkuchen mit Spargeln", "von": 4, "bis": 6, "z": 35, "k": "v", "zu": [[1, "Packung", "Flammkuchenteig"], [1, "Becher", "Crème fraîche"], [300, "g", "Grüne Spargeln"], [100, "g", "Ziegenfrischkäse"], [1, "", "Zwiebel, rot"], [1, "EL", "Honig"]], "vo": ["Salz", "Pfeffer", "Olivenöl"], "s": ["Ofen auf 240 °C vorheizen. Teig mit dem Papier auf ein Blech legen.", "Crème fraîche mit Salz und Pfeffer würzen und auf dem Teig verstreichen.", "Spargeln längs halbieren, Zwiebel in feine Ringe schneiden und darauf verteilen.", "Ziegenkäse darüberbröckeln und mit wenig Olivenöl beträufeln.", "12–15 Min knusprig backen und mit Honig beträufeln."]},
{"n": "Fondue chinoise", "von": 12, "bis": 1, "z": 60, "k": "f", "zu": [[600, "g", "Fleisch für Fondue chinoise, gemischt"], [1, "l", "Rindsbouillon"], [1, "Glas", "Cocktailsauce"], [1, "Glas", "Currysauce"], [1, "Glas", "Mixed Pickles"], [240, "g", "Langkornreis"], [150, "g", "Champignons"]], "vo": ["Sojasauce", "Salz", "Pfeffer"], "s": ["Fleisch einige Zeit vor dem Essen aus dem Kühlschrank nehmen und auf Tellern anrichten.", "Reis nach Packungsangabe kochen.", "Champignons in Scheiben schneiden.", "Bouillon mit etwas Sojasauce aufkochen und auf das Rechaud stellen.", "Fleisch und Champignons an der Gabel in der Bouillon garen und mit Saucen, Pickles und Reis essen."]},
{"n": "Forelle Müllerinnenart", "von": 4, "bis": 6, "z": 35, "k": "fi", "zu": [[3, "", "Forellen, ganz, küchenfertig"], [800, "g", "Kartoffeln, neue"], [1, "Bund", "Peterli"], [2, "", "Zitronen"], [60, "g", "Butter"]], "vo": ["Mehl", "Rapsöl", "Salz", "Pfeffer"], "s": ["Kartoffeln in Salzwasser 20 Min weich kochen.", "Forellen innen und aussen salzen und pfeffern, im Mehl wenden.", "In Rapsöl pro Seite 5–6 Min goldbraun braten.", "Öl abgiessen, Butter in die Pfanne geben, schäumen lassen und mit Zitronensaft ablöschen.", "Gehackten Peterli zugeben, Butter über die Forellen giessen und mit Kartoffeln servieren."]},
{"n": "Forelle mit Mandeln und Lauch", "von": 9, "bis": 11, "z": 35, "k": "fi", "zu": [[450, "g", "Forellenfilets"], [40, "g", "Mandelblättchen"], [2, "", "Lauch"], [1, "dl", "Halbrahm"], [600, "g", "Kartoffeln, festkochend"], [1, "", "Zitrone"]], "vo": ["Butter", "Mehl", "Muskat", "Salz", "Pfeffer"], "s": ["Kartoffeln in Salzwasser 20 Min kochen.", "Lauch in Ringe schneiden, in Butter weich dünsten, Halbrahm dazugeben und mit Muskat würzen.", "Forellenfilets würzen, im Mehl wenden und in Butter auf der Hautseite 3 Min braten, wenden und 1 Min fertig braten.", "Mandeln in Butter goldbraun rösten und mit Zitronensaft über den Fisch geben.", "Mit Lauchgemüse und Kartoffeln servieren."]},
{"n": "Forelle mit Ofentomaten", "von": 6, "bis": 9, "z": 40, "k": "fi", "zu": [[3, "", "Forellen, küchenfertig"], [500, "g", "Cherrytomaten"], [600, "g", "Frühkartoffeln"], [1, "", "Zitrone"], [1, "Bund", "Dill oder Peterli"], [50, "g", "Schwarze Oliven"]], "vo": ["Olivenöl", "Thymian", "Salz", "Pfeffer", "Knoblauch"], "s": ["Kartoffeln halbieren, mit Olivenöl, Salz und Thymian auf ein Blech geben und bei 200 °C 15 Min vorbacken.", "Forellen innen und aussen salzen und mit Zitronenscheiben und Kräutern füllen.", "Fische, Tomaten, Oliven und Knoblauch zu den Kartoffeln aufs Blech legen und mit Olivenöl beträufeln.", "Weitere 20 Min backen, bis sich die Rückenflosse leicht lösen lässt.", "Mit Zitronenschnitzen und frischen Kräutern servieren."]},
{"n": "Forellenfilets mit Bärlauchkruste", "von": 3, "bis": 4, "z": 35, "k": "fi", "zu": [[6, "", "Forellenfilets"], [1, "Bund", "Bärlauch"], [40, "g", "Paniermehl"], [50, "g", "Butter, weich"], [240, "g", "Langkornreis"], [1, "", "Zitrone"]], "vo": ["Salz", "Pfeffer", "Olivenöl"], "s": ["Ofen auf 220 °C vorheizen. Reis nach Packungsangabe kochen.", "Bärlauch fein hacken und mit Butter, Paniermehl und Salz verkneten.", "Filets mit der Hautseite nach unten auf ein geöltes Blech legen und würzen.", "Bärlauchmasse auf den Filets verstreichen.", "8–10 Min backen und mit Reis und Zitronenschnitzen servieren."]},
{"n": "Frühlings-Minestrone", "von": 4, "bis": 6, "z": 40, "k": "vg", "zu": [[2, "", "Rüebli"], [1, "", "Lauch, klein"], [1, "", "Zucchetti"], [150, "g", "Kefen"], [150, "g", "Erbsen"], [100, "g", "Suppenteigwaren"], [1, "Bund", "Basilikum"]], "vo": ["Olivenöl", "Knoblauch", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Rüebli, Lauch und Zucchetti in kleine Würfel schneiden, Kefen schräg halbieren.", "Rüebli, Lauch und Knoblauch in Olivenöl andünsten, mit Bouillon auffüllen.", "Teigwaren zugeben und 8 Min köcheln.", "Zucchetti, Kefen und Erbsen zugeben und 5 Min weiterkochen.", "Abschmecken, mit Basilikum und einem Schuss Olivenöl servieren."]},
{"n": "Gazpacho mit Brotcroûtons", "von": 7, "bis": 9, "z": 25, "k": "vg", "zu": [[1, "kg", "Tomaten, reif"], [1, "", "Gurke"], [1, "", "Peperoni, rot"], [1, "", "Zwiebel, rot"], [150, "g", "Weissbrot vom Vortag"], [3, "Zehe", "Knoblauch"]], "vo": ["Olivenöl", "Essig", "Salz", "Pfeffer", "Zucker"], "s": ["Tomaten, Gurke, Peperoni und Zwiebel grob würfeln, einen Teil davon für die Garnitur fein schneiden.", "Die Hälfte des Brotes einweichen, mit dem Gemüse und Knoblauch fein pürieren.", "Mit Olivenöl, Essig, Salz, Pfeffer und wenig Zucker abschmecken und mindestens 1 Std kühl stellen.", "Restliches Brot würfeln und in Olivenöl goldbraun rösten.", "Suppe kalt anrichten, mit Gemüsewürfeln und Croûtons bestreuen."]},
{"n": "Gedämpfter Zander asiatisch", "von": 3, "bis": 6, "z": 30, "k": "fi", "zu": [[450, "g", "Zanderfilet"], [1, "Bund", "Frühlingszwiebeln"], [1, "", "Ingwer, daumengross"], [300, "g", "Pak Choi"], [240, "g", "Jasminreis"], [1, "TL", "Sesamöl"]], "vo": ["Sojasauce", "Rapsöl", "Chili", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Ingwer und Frühlingszwiebeln in feine Streifen schneiden, Pak Choi halbieren.", "Fisch salzen und mit dem Pak Choi in einem Siebeinsatz über kochendem Wasser 8 Min dämpfen.", "Ingwer, Frühlingszwiebeln und Chili auf den Fisch legen, mit Sojasauce beträufeln.", "Öl stark erhitzen und zischend darübergiessen, mit Sesamöl beträufeln und mit Reis servieren."]},
{"n": "Gefüllte Peperoni mit Hackfleisch", "von": 7, "bis": 9, "z": 65, "k": "f", "zu": [[3, "", "Peperoni, gross"], [350, "g", "Rindshackfleisch"], [100, "g", "Langkornreis"], [1, "", "Zwiebel"], [1, "Dose", "Tomaten, gehackt"], [100, "g", "Feta"], [0.5, "Bund", "Peterli"]], "vo": ["Olivenöl", "Paprika", "Kreuzkümmel", "Salz", "Pfeffer", "Tomatenpüree", "Knoblauch"], "s": ["Reis 10 Min in Salzwasser vorkochen und abgiessen.", "Peperoni halbieren und entkernen.", "Zwiebel und Knoblauch andünsten, Hackfleisch krümelig anbraten, mit Gewürzen und Tomatenpüree würzen und mit Reis und Peterli mischen.", "Peperoni füllen, in eine Form setzen, Tomaten rundherum verteilen und Feta darüberbröckeln.", "Bei 200 °C 35 Min backen."]},
{"n": "Gefüllte Pouletbrust mit Bärlauch", "von": 3, "bis": 4, "z": 45, "k": "f", "zu": [[3, "", "Pouletbrüstli"], [1, "Bund", "Bärlauch"], [150, "g", "Frischkäse nature"], [6, "", "Tranchen Rohschinken"], [800, "g", "Kartoffeln, neue"]], "vo": ["Olivenöl", "Salz", "Pfeffer", "Rosmarin"], "s": ["Ofen auf 200 °C vorheizen. Kartoffeln halbieren, mit Olivenöl, Salz und Rosmarin aufs Blech geben und 35 Min backen.", "Bärlauch fein hacken und mit Frischkäse verrühren.", "In die Pouletbrüstli eine Tasche schneiden und mit der Masse füllen.", "Brüstli würzen, mit Rohschinken umwickeln und in Olivenöl rundum anbraten.", "Die letzten 20 Min zu den Kartoffeln in den Ofen geben."]},
{"n": "Gelbe Erbsensuppe mit Speck", "von": 11, "bis": 3, "z": 75, "k": "f", "zu": [[250, "g", "Gelbe Erbsen, getrocknet"], [150, "g", "Speck, am Stück"], [1, "", "Zwiebel"], [2, "", "Rüebli"], [1, "", "Lauch"], [300, "g", "Kartoffeln, mehligkochend"], [1, "Bund", "Peterli"]], "vo": ["Butter", "Gemüsebouillon", "Majoran", "Salz", "Pfeffer"], "s": ["Erbsen kalt abspülen, Gemüse und Kartoffeln würfeln.", "Zwiebel in Butter andünsten, Erbsen, Gemüse, Kartoffeln und Speck dazugeben.", "Mit Bouillon auffüllen und zugedeckt 60 Min köcheln, bis die Erbsen weich sind.", "Speck herausnehmen, in Würfel schneiden, Suppe grob pürieren.", "Speck zurückgeben, mit Majoran abschmecken und mit Peterli bestreuen."]},
{"n": "Gnocchi mit Rosenkohl und Salbei", "von": 10, "bis": 12, "z": 30, "k": "v", "zu": [[750, "g", "Gnocchi"], [400, "g", "Rosenkohl"], [50, "g", "Haselnüsse"], [60, "g", "Sbrinz"], [1, "Bund", "Salbei"]], "vo": ["Butter", "Salz", "Pfeffer", "Muskat"], "s": ["Rosenkohl rüsten, halbieren und in Salzwasser 5 Min vorkochen, abtropfen lassen.", "Haselnüsse grob hacken und ohne Fett rösten.", "Rosenkohl in Butter goldbraun anbraten, herausnehmen.", "Gnocchi in Butter knusprig braten, Salbei kurz mitbraten.", "Rosenkohl dazugeben, würzen und mit geriebenem Sbrinz und Nüssen servieren."]},
{"n": "Griechischer Salat mit Pita", "von": 6, "bis": 9, "z": 20, "k": "v", "zu": [[500, "g", "Tomaten"], [1, "", "Gurke"], [1, "", "Peperoni, grün"], [1, "", "Zwiebel, rot"], [200, "g", "Feta"], [100, "g", "Kalamata-Oliven"], [3, "", "Pitabrote"]], "vo": ["Olivenöl", "Essig", "Oregano", "Salz", "Pfeffer"], "s": ["Tomaten in Schnitze, Gurke in Halbmonde und Peperoni in Streifen schneiden.", "Zwiebel in feine Ringe schneiden und mit dem Gemüse und den Oliven mischen.", "Mit Olivenöl, Essig, Salz und Pfeffer anmachen.", "Feta in Stücken darauflegen, mit Oregano und etwas Olivenöl beträufeln.", "Pita kurz in der Pfanne erwärmen und dazu servieren."]},
{"n": "Grillierte Auberginen mit Tahini", "von": 7, "bis": 9, "z": 40, "k": "vg", "zu": [[3, "", "Auberginen"], [4, "EL", "Tahini"], [1, "", "Zitrone"], [1, "", "Granatapfel"], [1, "Bund", "Minze"], [200, "g", "Bulgur"], [50, "g", "Pinienkerne"]], "vo": ["Olivenöl", "Salz", "Kreuzkümmel", "Knoblauch", "Gemüsebouillon"], "s": ["Auberginen längs halbieren, das Fleisch kreuzweise einschneiden, mit Olivenöl bestreichen und salzen.", "Auf dem Grill oder bei 220 °C im Ofen 25 Min weich garen.", "Bulgur in Bouillon 10 Min quellen lassen.", "Tahini mit Zitronensaft, Knoblauch, Wasser und Salz zu einer glatten Sauce rühren.", "Auberginen auf dem Bulgur anrichten, mit Sauce, Granatapfelkernen, gerösteten Pinienkernen und Minze bestreuen."]},
{"n": "Grillierte Crevetten mit Couscous", "von": 6, "bis": 9, "z": 30, "k": "fi", "zu": [[450, "g", "Crevetten, roh, mit Schale"], [200, "g", "Couscous"], [1, "", "Gurke"], [250, "g", "Cherrytomaten"], [1, "", "Peperoni, rot"], [2, "", "Zitronen"], [1, "Bund", "Peterli"], [0.5, "Bund", "Minze"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Paprika", "Salz", "Gemüsebouillon"], "s": ["Crevetten mit Olivenöl, Knoblauch, Chili, Paprika und Zitronensaft 15 Min marinieren.", "Couscous mit heisser Bouillon übergiessen und 5 Min quellen lassen, mit einer Gabel auflockern.", "Gurke, Tomaten und Peperoni würfeln, mit Kräutern, Zitronensaft und Olivenöl unter den Couscous mischen.", "Crevetten auf dem Grill oder in der Grillpfanne je Seite 2 Min grillieren und salzen.", "Crevetten auf dem Couscous-Salat anrichten."]},
{"n": "Grüne Shakshuka", "von": 3, "bis": 5, "z": 30, "k": "v", "zu": [[400, "g", "Blattspinat"], [1, "Bund", "Frühlingszwiebeln"], [6, "", "Eier"], [100, "g", "Feta"], [1, "Bund", "Koriander oder Peterli"], [1, "", "Fladenbrot"]], "vo": ["Olivenöl", "Knoblauch", "Kreuzkümmel", "Chili", "Salz", "Pfeffer"], "s": ["Frühlingszwiebeln in Ringe schneiden und mit Knoblauch in Olivenöl andünsten.", "Spinat und Kreuzkümmel zugeben und zusammenfallen lassen, mit Salz und Chili würzen.", "Mulden formen, Eier hineinschlagen und zugedeckt 6–8 Min stocken lassen.", "Feta darüberbröseln und mit gehackten Kräutern bestreuen.", "Mit warmem Fladenbrot servieren."]},
{"n": "Halloumi-Gemüsespiesse", "von": 6, "bis": 9, "z": 40, "k": "v", "zu": [[2, "Packung", "Halloumi"], [2, "", "Zucchetti"], [2, "", "Peperoni"], [250, "g", "Cherrytomaten"], [1, "", "Zwiebel, rot"], [200, "g", "Couscous"], [1, "", "Zitrone"], [0.5, "Bund", "Minze"]], "vo": ["Olivenöl", "Honig", "Oregano", "Salz", "Pfeffer", "Gemüsebouillon"], "s": ["Halloumi, Zucchetti, Peperoni und Zwiebel in mundgerechte Stücke schneiden.", "Abwechselnd mit den Tomaten auf Spiesse stecken.", "Olivenöl, Zitronensaft, Honig und Oregano verrühren und die Spiesse damit bepinseln.", "Auf dem Grill oder in der Grillpfanne rundum 8–10 Min grillieren.", "Couscous mit heisser Bouillon übergiessen, 5 Min quellen lassen, Minze unterheben und mit den Spiessen servieren."]},
{"n": "Hamburger vom Grill", "von": 6, "bis": 8, "z": 40, "k": "f", "zu": [[450, "g", "Rindshackfleisch"], [3, "", "Burgerbrötchen"], [90, "g", "Cheddar, in Scheiben"], [2, "", "Tomaten"], [1, "", "Eisbergsalat, klein"], [1, "", "Zwiebel, rot"], [2, "", "Essiggurken"], [3, "", "Maiskolben"]], "vo": ["Senf", "Salz", "Pfeffer", "Rapsöl", "Butter", "Paprika"], "s": ["Hackfleisch mit Salz, Pfeffer und Paprika würzen und zu flachen Burgern formen.", "Maiskolben 10 Min vorkochen, dann mit Butter bestreichen und auf dem Grill rundum anrösten.", "Burger auf dem Grill je 3–4 Min pro Seite braten, zum Schluss mit Cheddar belegen.", "Brötchen halbieren und kurz rösten, Tomaten, Zwiebel und Essiggurken in Scheiben schneiden.", "Brötchen mit Senf, Salat, Gemüse und Burger belegen und mit dem Mais servieren."]},
{"n": "Hörnli mit Ghackets", "von": 1, "bis": 12, "z": 30, "k": "f", "zu": [[350, "g", "Hörnli"], [400, "g", "Hackfleisch, Rind"], [1, "", "Zwiebel"], [1, "dl", "Rotwein"], [60, "g", "Sbrinz, gerieben"], [1, "Glas", "Apfelmus"]], "vo": ["Rapsöl", "Tomatenpüree", "Mehl", "Gemüsebouillon", "Salz", "Pfeffer", "Paprika"], "s": ["Hörnli in Salzwasser al dente kochen.", "Zwiebel fein hacken, Hackfleisch in Öl krümelig anbraten, Zwiebel dazugeben.", "Tomatenpüree und etwas Mehl mitrösten, mit Rotwein und Bouillon ablöschen.", "10 Min köcheln, mit Paprika, Salz und Pfeffer abschmecken.", "Hörnli mit dem Ghackets anrichten, Käse darüberstreuen und Apfelmus dazu servieren."]},
{"n": "Japanisches Curry mit Poulet", "von": 11, "bis": 3, "z": 45, "k": "f", "zu": [[450, "g", "Pouletbrust"], [2, "", "Rüebli"], [2, "", "Kartoffeln, festkochend"], [1, "", "Zwiebel"], [1, "", "Apfel"], [1, "Packung", "Japanische Currywürfel"], [240, "g", "Japanischer Rundkornreis"]], "vo": ["Rapsöl", "Sojasauce", "Honig", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Poulet, Rüebli, Kartoffeln und Zwiebel in Stücke schneiden, Apfel fein reiben.", "Poulet und Zwiebel in Öl anbraten, Gemüse und Apfel dazugeben.", "Mit Wasser knapp bedecken und 20 Min köcheln, bis das Gemüse weich ist.", "Currywürfel einrühren, mit Sojasauce und Honig abschmecken und 5 Min sämig köcheln, mit dem Reis servieren."]},
{"n": "Kabeljau auf Beluga-Linsen", "von": 9, "bis": 12, "z": 40, "k": "fi", "zu": [[450, "g", "Kabeljaufilet"], [180, "g", "Beluga-Linsen"], [2, "", "Rüebli"], [1, "", "Schalotte"], [100, "g", "Knollensellerie"], [1, "dl", "Halbrahm"], [0.5, "Bund", "Peterli"]], "vo": ["Olivenöl", "Butter", "Senf", "Essig", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Linsen in Bouillon 20 Min weich kochen.", "Rüebli, Sellerie und Schalotte fein würfeln und in Butter andünsten.", "Linsen dazugeben, mit Essig, Senf und Halbrahm abschmecken.", "Kabeljau würzen und in Öl auf jeder Seite 3 Min braten.", "Fisch auf den Linsen anrichten und mit Peterli bestreuen."]},
{"n": "Kabeljau auf Wirz mit Senfsauce", "von": 11, "bis": 2, "z": 40, "k": "fi", "zu": [[450, "g", "Kabeljaufilet"], [500, "g", "Wirz"], [1, "", "Schalotte"], [2, "dl", "Rahm"], [1, "EL", "Grobkörniger Senf"], [600, "g", "Kartoffeln, festkochend"]], "vo": ["Butter", "Rapsöl", "Mehl", "Gemüsebouillon", "Salz", "Pfeffer", "Muskat"], "s": ["Kartoffeln schälen und in Salzwasser 20 Min kochen.", "Wirz in feine Streifen schneiden, in Butter andünsten, mit wenig Bouillon 10 Min garen, mit Muskat würzen.", "Schalotte hacken, in Butter andünsten, mit Rahm aufkochen und Senf einrühren.", "Fisch salzen, leicht mehlen und in Öl je Seite 3 Min braten.", "Fisch auf dem Wirz anrichten, Senfsauce und Kartoffeln dazu servieren."]},
{"n": "Kabeljau mit Erbsenpüree", "von": 5, "bis": 6, "z": 30, "k": "fi", "zu": [[450, "g", "Kabeljaufilet"], [500, "g", "Erbsen"], [400, "g", "Kartoffeln, mehligkochend"], [1, "dl", "Milch"], [0.5, "Bund", "Minze"], [1, "", "Zitrone"]], "vo": ["Butter", "Olivenöl", "Salz", "Pfeffer"], "s": ["Kartoffeln schälen, würfeln und in Salzwasser 15 Min kochen. Erbsen die letzten 5 Min mitkochen.", "Abgiessen, mit warmer Milch, Butter und Minze grob pürieren und abschmecken.", "Fisch in Portionen schneiden, salzen und pfeffern.", "In Olivenöl auf der Hautseite 4 Min braten, wenden und 2 Min fertig garen.", "Fisch auf dem Püree anrichten und mit Zitronensaft beträufeln."]},
{"n": "Kalbsschnitzel mit Erbsenpüree", "von": 5, "bis": 6, "z": 30, "k": "f", "zu": [[3, "", "Kalbsschnitzel (à ca. 140 g)"], [500, "g", "Erbsen"], [300, "g", "Kartoffeln, mehligkochend"], [1, "dl", "Halbrahm"], [0.5, "Bund", "Minze"], [1, "", "Zitrone"]], "vo": ["Butter", "Mehl", "Salz", "Pfeffer", "Muskat"], "s": ["Kartoffeln schälen, würfeln und in Salzwasser 15 Min kochen. Erbsen die letzten 5 Min mitkochen.", "Abgiessen und mit Rahm, Butter und Minze pürieren, mit Salz und Muskat würzen.", "Schnitzel würzen und leicht mit Mehl bestäuben.", "In Butter pro Seite 2 Min braten.", "Schnitzel mit Erbsenpüree und Zitronenschnitzen servieren."]},
{"n": "Kalte Gurkensuppe mit Dill", "von": 6, "bis": 8, "z": 20, "k": "v", "zu": [[2, "", "Gurken"], [400, "g", "Joghurt nature"], [1, "dl", "Halbrahm"], [1, "Bund", "Dill"], [1, "", "Zitrone"], [1, "", "Bauernbrot"], [100, "g", "Feta"]], "vo": ["Olivenöl", "Salz", "Pfeffer", "Knoblauch"], "s": ["Gurken schälen, entkernen und grob schneiden, ein kleines Stück fein würfeln.", "Gurken mit Joghurt, Halbrahm, Dill, Knoblauch und Zitronensaft fein pürieren.", "Mit Salz und Pfeffer abschmecken und 30 Min kühl stellen.", "Suppe in Teller verteilen, mit Gurkenwürfeln, zerbröckeltem Feta und Olivenöl garnieren.", "Mit Bauernbrot servieren."]},
{"n": "Kartoffelgratin", "von": 1, "bis": 12, "z": 75, "k": "v", "zu": [[1, "kg", "Kartoffeln, mehligkochend"], [3, "dl", "Rahm"], [2, "dl", "Milch"], [100, "g", "Greyerzer, gerieben"], [200, "g", "Blattsalat"]], "vo": ["Butter", "Knoblauch", "Salz", "Pfeffer", "Muskat", "Essig", "Olivenöl"], "s": ["Ofen auf 180 °C vorheizen, Gratinform mit Knoblauch ausreiben und buttern.", "Kartoffeln schälen und in dünne Scheiben hobeln.", "Rahm und Milch mit Salz, Pfeffer und Muskat aufkochen, Kartoffeln darin 5 Min ziehen lassen.", "Alles in die Form geben, mit Käse bestreuen und 50 Min backen.", "Salat mit einer Essig-Öl-Sauce dazu servieren."]},
{"n": "Kichererbsen-Spinat-Curry", "von": 3, "bis": 5, "z": 30, "k": "vg", "zu": [[2, "Dose", "Kichererbsen"], [1, "Dose", "Tomaten, gehackt (400 g)"], [1, "Dose", "Kokosmilch"], [300, "g", "Blattspinat"], [1, "", "Zwiebel"], [1, "", "Ingwer, daumengross"], [240, "g", "Basmatireis"]], "vo": ["Rapsöl", "Knoblauch", "Curry", "Kreuzkümmel", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Zwiebel, Knoblauch und Ingwer fein hacken und in Öl andünsten. Curry und Kreuzkümmel kurz mitrösten.", "Tomaten, Kokosmilch und abgespülte Kichererbsen zugeben und 15 Min köcheln.", "Spinat unterrühren und zusammenfallen lassen.", "Mit Salz abschmecken und mit dem Reis servieren."]},
{"n": "Kichererbsen-Süsskartoffel-Curry", "von": 11, "bis": 3, "z": 40, "k": "vg", "zu": [[500, "g", "Süsskartoffeln"], [1, "Dose", "Kichererbsen"], [1, "", "Zwiebel"], [4, "dl", "Kokosmilch"], [100, "g", "Blattspinat"], [240, "g", "Jasminreis"], [1, "", "Limette"]], "vo": ["Rapsöl", "Knoblauch", "Curry", "Kreuzkümmel", "Gemüsebouillon", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Zwiebel und Knoblauch hacken, Süsskartoffeln schälen und würfeln.", "Zwiebel in Öl andünsten, Curry und Kreuzkümmel mitrösten, Süsskartoffeln dazugeben.", "Mit Kokosmilch und wenig Bouillon ablöschen und 15 Min köcheln.", "Abgetropfte Kichererbsen und Spinat dazugeben, kurz erhitzen, mit Limettensaft abschmecken."]},
{"n": "Käsefondue moitié-moitié", "von": 11, "bis": 2, "z": 30, "k": "v", "zu": [[400, "g", "Greyerzer, gerieben"], [400, "g", "Vacherin fribourgeois, gerieben"], [3, "dl", "Weisswein, trocken"], [1, "Zehe", "Knoblauch"], [1, "EL", "Maizena"], [0.5, "dl", "Kirsch"], [600, "g", "Ruchbrot"]], "vo": ["Pfeffer", "Muskat"], "s": ["Brot in mundgerechte Würfel schneiden, jedes Stück mit Rinde.", "Caquelon mit der halbierten Knoblauchzehe ausreiben.", "Wein im Caquelon erwärmen, Käse nach und nach unter Rühren in Achterbewegungen schmelzen lassen.", "Maizena mit Kirsch glatt rühren, unter das Fondue mischen und kurz aufkochen.", "Mit Pfeffer und Muskat würzen, auf dem Rechaud servieren und Brot eintauchen."]},
{"n": "Kürbis-Kichererbsen-Curry", "von": 9, "bis": 12, "z": 40, "k": "vg", "zu": [[600, "g", "Kürbis"], [1, "Dose", "Kichererbsen"], [1, "Dose", "Kokosmilch"], [100, "g", "Blattspinat"], [1, "", "Zwiebel"], [20, "g", "Ingwer"], [240, "g", "Basmatireis"], [1, "", "Limette"]], "vo": ["Rapsöl", "Knoblauch", "Curry", "Kreuzkümmel", "Salz"], "s": ["Kürbis würfeln, Zwiebel, Knoblauch und Ingwer fein hacken.", "Zwiebel, Knoblauch und Ingwer in Öl andünsten, Gewürze kurz mitrösten.", "Kürbis, abgetropfte Kichererbsen und Kokosmilch dazugeben und 20 Min köcheln.", "Reis nach Packungsangabe kochen.", "Spinat unter das Curry ziehen und zusammenfallen lassen.", "Mit Limettensaft und Salz abschmecken und mit Reis servieren."]},
{"n": "Kürbisrisotto mit Salbei", "von": 9, "bis": 11, "z": 35, "k": "v", "zu": [[400, "g", "Butternuss-Kürbis"], [240, "g", "Risottoreis"], [1, "", "Zwiebel"], [1, "dl", "Weisswein"], [60, "g", "Parmesan"], [1, "Bund", "Salbei"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Kürbis in Würfel schneiden, Zwiebel fein hacken.", "Beides in Butter andünsten, Reis 2 Min mitdünsten.", "Mit Wein ablöschen. Nach und nach heisse Bouillon dazugeben und 18 Min rühren, bis der Reis cremig ist.", "Salbeiblätter in wenig Butter knusprig braten.", "Parmesan unterrühren, abschmecken, Salbei darüber."]},
{"n": "Kürbissuppe mit Ingwer", "von": 9, "bis": 12, "z": 35, "k": "vg", "zu": [[800, "g", "Hokkaido-Kürbis"], [1, "", "Zwiebel"], [20, "g", "Ingwer"], [1, "Dose", "Kokosmilch"], [1, "", "Limette"], [40, "g", "Kürbiskerne"], [1, "", "Ruchbrot"]], "vo": ["Rapsöl", "Gemüsebouillon", "Curry", "Salz", "Pfeffer"], "s": ["Kürbis entkernen und mit Schale würfeln. Zwiebel und Ingwer fein hacken.", "Zwiebel und Ingwer in Öl andünsten, Kürbis und Curry kurz mitdünsten.", "Mit Bouillon knapp bedecken und 20 Min köcheln.", "Kokosmilch dazugeben und alles fein pürieren.", "Mit Limettensaft, Salz und Pfeffer abschmecken.", "Kürbiskerne ohne Fett rösten, darüberstreuen und mit Brot servieren."]},
{"n": "Lachs auf Lauch-Linsen", "von": 11, "bis": 3, "z": 40, "k": "fi", "zu": [[450, "g", "Lachsfilet"], [200, "g", "Belugalinsen"], [2, "", "Lauch"], [1, "dl", "Rahm"], [1, "", "Zitrone"]], "vo": ["Butter", "Rapsöl", "Gemüsebouillon", "Senf", "Salz", "Pfeffer"], "s": ["Linsen in Bouillon 20 Min weich kochen, abgiessen.", "Lauch in feine Ringe schneiden und in Butter 5 Min andünsten.", "Linsen und Rahm dazugeben, mit Senf, Zitronensaft, Salz und Pfeffer abschmecken.", "Lachs in Portionen schneiden, salzen und in Öl auf der Hautseite 5 Min braten, wenden und 2 Min fertig garen.", "Lachs auf den Lauch-Linsen anrichten."]},
{"n": "Lachs mit Ofenfenchel", "von": 9, "bis": 11, "z": 40, "k": "fi", "zu": [[450, "g", "Lachsfilet"], [2, "", "Fenchel"], [500, "g", "Kartoffeln, festkochend"], [1, "", "Zitrone"], [50, "g", "Oliven, schwarz"]], "vo": ["Olivenöl", "Knoblauch", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen. Kartoffeln in Schnitze und Fenchel in Spalten schneiden.", "Gemüse mit Öl, Knoblauch und Salz mischen und auf dem Blech 25 Min backen.", "Lachs in Portionen schneiden, würzen und mit Zitronenscheiben und Oliven aufs Gemüse legen.", "Weitere 12 Min backen, bis der Lachs gar ist.", "Mit Zitronensaft und Fenchelgrün servieren."]},
{"n": "Lachs mit grünen Spargeln vom Blech", "von": 4, "bis": 6, "z": 35, "k": "fi", "zu": [[450, "g", "Lachsfilet"], [500, "g", "Grüne Spargeln"], [600, "g", "Kartoffeln, neue"], [1, "", "Zitrone, unbehandelt"], [0.5, "Bund", "Dill"]], "vo": ["Olivenöl", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen. Kartoffeln halbieren, mit Olivenöl und Salz aufs Blech geben und 20 Min backen.", "Holzige Spargelenden abschneiden, Spargeln mit Olivenöl und Salz mischen.", "Lachs in Portionen schneiden, würzen und mit Zitronenscheiben belegen.", "Spargeln und Lachs zu den Kartoffeln aufs Blech legen und 12–15 Min backen.", "Mit Dill bestreuen und servieren."]},
{"n": "Lachsspiesse mit Gurkensalat", "von": 6, "bis": 8, "z": 35, "k": "fi", "zu": [[450, "g", "Lachsfilet ohne Haut"], [2, "", "Gurken"], [180, "g", "Joghurt nature"], [1, "Bund", "Dill"], [1, "", "Zitrone"], [1, "", "Zucchetti"], [240, "g", "Langkornreis"]], "vo": ["Olivenöl", "Senf", "Honig", "Salz", "Pfeffer"], "s": ["Reis garen.", "Lachs und Zucchetti in Würfel schneiden und abwechselnd auf Spiesse stecken.", "Spiesse mit Olivenöl, Zitronensaft, Salz und Pfeffer würzen und auf dem Grill oder in der Grillpfanne 6–8 Min rundum grillieren.", "Gurken hobeln, leicht salzen und mit Joghurt, Senf, Honig und gehacktem Dill mischen.", "Spiesse mit Gurkensalat und Reis servieren."]},
{"n": "Lamm-Köfte mit Radiesli-Salat", "von": 4, "bis": 6, "z": 35, "k": "f", "zu": [[450, "g", "Lammhackfleisch"], [1, "", "Zwiebel"], [1, "Bund", "Peterli"], [1, "Bund", "Radiesli"], [1, "", "Gurke"], [1, "Becher", "Joghurt nature"], [3, "", "Fladenbrote"]], "vo": ["Knoblauch", "Kreuzkümmel", "Paprika", "Olivenöl", "Salz", "Pfeffer"], "s": ["Zwiebel fein reiben, Peterli hacken. Mit Hackfleisch, Gewürzen und Salz gut verkneten.", "Längliche Köfte formen und in Olivenöl rundum 8 Min braten.", "Radiesli und Gurke in Scheiben schneiden, mit Olivenöl, Salz und etwas Peterli mischen.", "Joghurt mit wenig Knoblauch und Salz verrühren.", "Köfte mit Salat, Joghurtsauce und warmem Fladenbrot servieren."]},
{"n": "Lammcurry mit Spinat", "von": 3, "bis": 5, "z": 75, "k": "f", "zu": [[450, "g", "Lammschulter, gewürfelt"], [1, "", "Zwiebel"], [1, "", "Ingwer, daumengross"], [1, "Dose", "Tomaten, gehackt (400 g)"], [1, "Becher", "Joghurt nature"], [300, "g", "Blattspinat"], [240, "g", "Basmatireis"]], "vo": ["Rapsöl", "Knoblauch", "Curry", "Kreuzkümmel", "Zimt", "Salz"], "s": ["Lamm portionenweise im heissen Öl anbraten, herausnehmen.", "Zwiebel, Knoblauch und Ingwer hacken und andünsten, Gewürze kurz mitrösten.", "Fleisch, Tomaten und etwas Wasser zugeben und zugedeckt 50 Min schmoren.", "Reis nach Packungsangabe kochen.", "Spinat unterrühren, Joghurt zugeben, abschmecken und mit Reis servieren."]},
{"n": "Lammkoteletts mit Bärlauchbutter", "von": 3, "bis": 4, "z": 35, "k": "f", "zu": [[9, "", "Lammkoteletts"], [800, "g", "Kartoffeln, neue"], [80, "g", "Butter, weich"], [0.5, "Bund", "Bärlauch"], [1, "", "Zitrone, unbehandelt"]], "vo": ["Olivenöl", "Salz", "Pfeffer"], "s": ["Kartoffeln halbieren und in Salzwasser 15 Min kochen.", "Bärlauch fein hacken, mit Butter, Zitronenschale und Salz verrühren, kalt stellen.", "Kartoffeln abgiessen und in Olivenöl goldbraun braten.", "Koteletts würzen und pro Seite 2–3 Min in Olivenöl braten.", "Koteletts mit Kartoffeln anrichten und je ein Stück Bärlauchbutter daraufgeben."]},
{"n": "Lammkoteletts mit Minz-Zucchetti", "von": 6, "bis": 9, "z": 35, "k": "f", "zu": [[9, "", "Lammkoteletts"], [3, "", "Zucchetti"], [1, "Bund", "Minze"], [1, "", "Zitrone, unbehandelt"], [600, "g", "Frühkartoffeln"], [150, "g", "Griechischer Joghurt"]], "vo": ["Olivenöl", "Rosmarin", "Salz", "Pfeffer", "Knoblauch"], "s": ["Kartoffeln halbieren, mit Olivenöl und Rosmarin mischen und bei 200 °C 30 Min im Ofen rösten.", "Lammkoteletts mit Olivenöl, Knoblauch, Zitronenschale und Pfeffer marinieren.", "Zucchetti längs in Scheiben schneiden und in der Grillpfanne beidseitig grillieren, mit Zitronensaft, Minze, Olivenöl und Salz anmachen.", "Koteletts auf dem Grill oder in der Pfanne je 2–3 Min pro Seite braten und salzen.", "Mit Zucchetti, Kartoffeln und Joghurt servieren."]},
{"n": "Lasagne Bolognese", "von": 1, "bis": 12, "z": 100, "k": "f", "zu": [[400, "g", "Hackfleisch, Rind"], [1, "", "Zwiebel"], [1, "", "Rüebli"], [2, "Dose", "Pelati"], [1, "dl", "Rotwein"], [250, "g", "Lasagneblätter"], [5, "dl", "Milch"], [80, "g", "Parmesan"]], "vo": ["Olivenöl", "Butter", "Mehl", "Knoblauch", "Tomatenpüree", "Oregano", "Muskat", "Salz", "Pfeffer"], "s": ["Zwiebel, Rüebli und Knoblauch fein hacken und in Öl andünsten. Hackfleisch dazugeben und krümelig braten.", "Tomatenpüree mitrösten, mit Wein ablöschen, Pelati und Oregano dazugeben und 30 Min köcheln.", "Butter schmelzen, Mehl darin andünsten, Milch einrühren und zu einer dicken Béchamel kochen. Mit Muskat würzen.", "Ofen auf 200 °C vorheizen. Sauce, Lasagneblätter und Béchamel abwechselnd in eine Form schichten.", "Mit Béchamel und Parmesan abschliessen und 35 Min backen. Vor dem Schneiden 10 Min ruhen lassen."]},
{"n": "Lauchwähe", "von": 9, "bis": 3, "z": 60, "k": "v", "zu": [[1, "Packung", "Kuchenteig, rund"], [500, "g", "Lauch"], [100, "g", "Greyerzer"], [2, "", "Eier"], [2, "dl", "Halbrahm"], [1, "dl", "Milch"], [150, "g", "Blattsalat"]], "vo": ["Butter", "Muskat", "Salz", "Pfeffer", "Essig", "Rapsöl"], "s": ["Ofen auf 220 °C vorheizen. Teig mit dem Backpapier ins Blech legen und den Boden mit einer Gabel einstechen.", "Lauch in feine Ringe schneiden und in Butter 5 Min dünsten, leicht abkühlen lassen.", "Käse reiben und auf dem Teig verteilen, Lauch darüber geben.", "Eier, Halbrahm und Milch verquirlen, mit Muskat, Salz und Pfeffer würzen und darübergiessen.", "In der unteren Ofenhälfte 30 Min backen und mit Salat servieren."]},
{"n": "Linguine mit Crevetten", "von": 6, "bis": 9, "z": 30, "k": "fi", "zu": [[350, "g", "Linguine"], [350, "g", "Crevetten, roh, geschält"], [400, "g", "Cherrytomaten"], [1, "dl", "Weisswein"], [0.5, "Bund", "Peterli"], [1, "", "Zitrone, unbehandelt"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Linguine in Salzwasser al dente kochen.", "Knoblauch und Chili in Olivenöl andünsten, Crevetten 2 Min anbraten und herausnehmen.", "Halbierte Tomaten in die Pfanne geben, mit Wein ablöschen und 5 Min köcheln.", "Crevetten, Pasta und etwas Kochwasser dazugeben und gut schwenken.", "Mit Zitronenschale und Peterli bestreuen und servieren."]},
{"n": "Linguine mit Crevetten und Spargeln", "von": 4, "bis": 6, "z": 25, "k": "fi", "zu": [[350, "g", "Linguine"], [300, "g", "Crevetten, roh, geschält"], [300, "g", "Grüne Spargeln"], [1, "dl", "Weisswein"], [1, "", "Zitrone, unbehandelt"], [0.5, "Bund", "Peterli"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Linguine in Salzwasser al dente kochen.", "Spargeln schräg in Stücke schneiden und in Olivenöl 4 Min braten.", "Knoblauch, Chili und Crevetten zugeben und 2 Min braten.", "Mit Wein ablöschen und kurz einköcheln, Zitronenschale zugeben.", "Linguine mit etwas Kochwasser untermischen, mit Peterli und Zitronensaft abschmecken."]},
{"n": "Linsen-Dal mit Spinat", "von": 1, "bis": 12, "z": 40, "k": "vg", "zu": [[250, "g", "Rote Linsen"], [1, "", "Zwiebel"], [20, "g", "Ingwer"], [1, "Dose", "Pelati"], [2, "dl", "Kokosmilch"], [150, "g", "Blattspinat"], [240, "g", "Basmatireis"]], "vo": ["Rapsöl", "Knoblauch", "Curry", "Kreuzkümmel", "Gemüsebouillon", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Zwiebel, Knoblauch und Ingwer hacken und in Öl andünsten, Curry und Kreuzkümmel kurz mitrösten.", "Linsen, Pelati und Bouillon dazugeben und 15 Min köcheln, bis die Linsen zerfallen.", "Kokosmilch und Spinat unterrühren, bis der Spinat zusammenfällt.", "Mit Salz abschmecken und mit dem Reis servieren."]},
{"n": "Luganighe mit Polenta", "von": 9, "bis": 3, "z": 45, "k": "f", "zu": [[450, "g", "Luganighe"], [250, "g", "Bramata-Polenta"], [3, "", "Zwiebeln"], [2, "dl", "Merlot"], [60, "g", "Parmesan"]], "vo": ["Butter", "Olivenöl", "Gemüsebouillon", "Zucker", "Essig", "Salz", "Pfeffer"], "s": ["Polenta in Bouillon einrühren und bei kleiner Hitze unter gelegentlichem Rühren 30 Min quellen lassen.", "Zwiebeln in Ringe schneiden und in Öl langsam weich dünsten. Mit wenig Zucker karamellisieren.", "Mit Merlot und einem Schuss Essig ablöschen und sirupartig einkochen.", "Luganighe in einer Pfanne rundum 15 Min braten.", "Butter und Parmesan unter die Polenta rühren und mit Wurst und Zwiebeln servieren."]},
{"n": "Maissalat mit schwarzen Bohnen", "von": 7, "bis": 9, "z": 30, "k": "vg", "zu": [[3, "", "Maiskolben"], [2, "Dose", "Schwarze Bohnen"], [1, "", "Peperoni, rot"], [2, "", "Avocados"], [250, "g", "Cherrytomaten"], [1, "", "Zwiebel, rot"], [2, "", "Limetten"], [1, "Bund", "Koriander"], [6, "", "Tortillas"]], "vo": ["Olivenöl", "Kreuzkümmel", "Chili", "Salz", "Pfeffer"], "s": ["Maiskolben 10 Min in Wasser kochen, dann in einer Grillpfanne rundum anrösten und die Körner abschneiden.", "Bohnen abspülen, Peperoni, Avocados und Zwiebel würfeln, Tomaten halbieren.", "Alles mit Limettensaft, Olivenöl, Kreuzkümmel, Chili und Salz mischen.", "Koriander hacken und unterheben.", "Tortillas kurz erwärmen und mit dem Salat servieren."]},
{"n": "Marronisuppe", "von": 10, "bis": 12, "z": 35, "k": "v", "zu": [[400, "g", "Marroni, geschält"], [1, "", "Zwiebel"], [1, "", "Apfel"], [1, "dl", "Rahm"], [0.5, "dl", "Portwein"], [1, "", "Ruchbrot"]], "vo": ["Butter", "Gemüsebouillon", "Muskat", "Salz", "Pfeffer"], "s": ["Zwiebel und Apfel klein schneiden und in Butter andünsten.", "Marroni kurz mitdünsten, einige für die Garnitur beiseitelegen.", "Mit Bouillon bedecken und 20 Min köcheln.", "Rahm und Portwein dazugeben und fein pürieren.", "Mit Muskat, Salz und Pfeffer abschmecken. Beiseitegelegte Marroni in Butter braten, darüber geben und mit Brot servieren."]},
{"n": "Melanzane alla Parmigiana", "von": 7, "bis": 9, "z": 75, "k": "v", "zu": [[2, "", "Auberginen, gross"], [2, "Dose", "Tomaten, gehackt"], [2, "", "Mozzarella"], [80, "g", "Parmesan"], [1, "Bund", "Basilikum"], [1, "", "Zwiebel"], [1, "", "Ciabatta"]], "vo": ["Olivenöl", "Salz", "Pfeffer", "Knoblauch", "Zucker"], "s": ["Auberginen längs in Scheiben schneiden, salzen und 15 Min ziehen lassen, dann trocken tupfen.", "Scheiben in Olivenöl beidseitig goldbraun braten.", "Zwiebel und Knoblauch andünsten, Tomaten dazugeben, würzen und 15 Min einköcheln.", "Sauce, Auberginen, Mozzarellascheiben, Basilikum und Parmesan lagenweise in eine Form schichten.", "Bei 200 °C 30 Min backen und mit Brot servieren."]},
{"n": "Mie-Nudeln mit Poulet und Chinakohl", "von": 9, "bis": 2, "z": 30, "k": "f", "zu": [[400, "g", "Pouletbrust"], [250, "g", "Mie-Nudeln"], [400, "g", "Chinakohl"], [2, "", "Rüebli"], [1, "Bund", "Frühlingszwiebeln"], [20, "g", "Ingwer"]], "vo": ["Rapsöl", "Sojasauce", "Knoblauch", "Honig", "Chili"], "s": ["Nudeln nach Packungsangabe garen und abtropfen lassen.", "Poulet in Streifen schneiden, mit Sojasauce marinieren und im Wok portionenweise heiss anbraten. Herausnehmen.", "Rüebli in Stäbchen, Chinakohl in Streifen und Frühlingszwiebeln in Ringe schneiden.", "Knoblauch und Ingwer im Wok anbraten, Gemüse 4 Min pfannenrühren.", "Nudeln, Poulet, Sojasauce, Honig und Chili dazugeben und alles gut durchschwenken."]},
{"n": "Moules marinières mit Frites", "von": 10, "bis": 3, "z": 45, "k": "fi", "zu": [[2, "kg", "Miesmuscheln"], [2, "", "Schalotten"], [2, "dl", "Weisswein"], [1, "dl", "Rahm"], [1, "Bund", "Peterli"], [750, "g", "Pommes frites, tiefgekühlt"]], "vo": ["Butter", "Knoblauch", "Pfeffer", "Salz"], "s": ["Pommes frites nach Packungsangabe im Ofen backen.", "Muscheln gründlich waschen, Bärte entfernen, offene Muscheln wegwerfen.", "Schalotten und Knoblauch fein hacken und in einem grossen Topf in Butter andünsten.", "Muscheln und Wein dazugeben, zugedeckt 5–6 Min kochen, bis sich die Muscheln öffnen, dabei schütteln.", "Rahm und gehackten Peterli unterrühren, geschlossene Muscheln entfernen und mit den Frites servieren."]},
{"n": "Moussaka", "von": 7, "bis": 9, "z": 90, "k": "f", "zu": [[2, "", "Auberginen"], [500, "g", "Lammhackfleisch oder Rindshackfleisch"], [1, "", "Zwiebel"], [1, "Dose", "Tomaten, gehackt"], [5, "dl", "Milch"], [50, "g", "Butter"], [80, "g", "Parmesan"], [1, "", "Ei"], [400, "g", "Kartoffeln"]], "vo": ["Olivenöl", "Mehl", "Zimt", "Oregano", "Muskat", "Salz", "Pfeffer", "Knoblauch"], "s": ["Auberginen und Kartoffeln in Scheiben schneiden, mit Olivenöl bestreichen und bei 220 °C 15 Min vorbacken.", "Zwiebel und Knoblauch andünsten, Hackfleisch anbraten, Tomaten, Zimt und Oregano dazugeben und 20 Min köcheln.", "Butter schmelzen, Mehl darin andünsten, Milch einrühren und zu einer dicken Béchamel kochen, vom Herd nehmen und Ei, Parmesan und Muskat unterrühren.", "Kartoffeln, Auberginen und Fleischsauce in eine Form schichten, mit Béchamel abschliessen.", "Bei 180 °C 40 Min backen und vor dem Anschneiden 10 Min ruhen lassen."]},
{"n": "Navarin (Lammragout mit Gemüse)", "von": 4, "bis": 5, "z": 100, "k": "f", "zu": [[500, "g", "Lammragout"], [1, "", "Zwiebel"], [3, "", "Rüebli"], [500, "g", "Kartoffeln, neue"], [200, "g", "Erbsen"], [1, "dl", "Weisswein"], [1, "Bund", "Peterli"]], "vo": ["Olivenöl", "Knoblauch", "Mehl", "Tomatenpüree", "Gemüsebouillon", "Thymian", "Salz", "Pfeffer"], "s": ["Fleisch würzen, mit Mehl bestäuben und im Olivenöl kräftig anbraten.", "Zwiebel und Knoblauch zugeben, Tomatenpüree kurz mitrösten. Mit Wein und Bouillon ablöschen, Thymian zugeben.", "Zugedeckt 45 Min schmoren.", "Rüebli und Kartoffeln in Stücke schneiden, zugeben und 25 Min weiterschmoren.", "Erbsen 5 Min mitgaren, abschmecken und mit Peterli bestreuen."]},
{"n": "Neue Kartoffeln mit Kräuterquark", "von": 5, "bis": 6, "z": 30, "k": "v", "zu": [[1, "kg", "Kartoffeln, neue"], [500, "g", "Magerquark"], [1, "Becher", "Sauerrahm"], [1, "Bund", "Schnittlauch"], [1, "Bund", "Radiesli"], [0.5, "Bund", "Dill"]], "vo": ["Salz", "Pfeffer", "Olivenöl", "Knoblauch"], "s": ["Kartoffeln gut waschen und in der Schale in Salzwasser 20 Min weich kochen.", "Quark mit Sauerrahm und wenig gepresstem Knoblauch glatt rühren.", "Schnittlauch und Dill fein schneiden und unterrühren, mit Salz und Pfeffer würzen.", "Radiesli in feine Scheiben schneiden und unter den Quark mischen oder darüberstreuen.", "Kartoffeln halbieren, mit etwas Olivenöl beträufeln und mit dem Quark servieren."]},
{"n": "Nudeln mit Kefen und Erdnusssauce", "von": 5, "bis": 7, "z": 25, "k": "vg", "zu": [[300, "g", "Mie-Nudeln"], [250, "g", "Kefen"], [2, "", "Rüebli"], [1, "Bund", "Frühlingszwiebeln"], [4, "EL", "Erdnussbutter"], [1, "", "Limette"], [50, "g", "Erdnüsse, geröstet"]], "vo": ["Sojasauce", "Rapsöl", "Knoblauch", "Chili", "Zucker"], "s": ["Nudeln nach Packungsangabe kochen und abtropfen.", "Erdnussbutter mit Sojasauce, Limettensaft, Zucker, Chili und warmem Wasser glatt rühren.", "Rüebli in Streifen schneiden, Frühlingszwiebeln in Ringe, Kefen halbieren.", "Gemüse mit Knoblauch im heissen Öl 3 Min pfannenrühren.", "Nudeln und Sauce zugeben und gut mischen. Mit gehackten Erdnüssen bestreuen."]},
{"n": "Nüsslisalat mit Ei und Croûtons", "von": 11, "bis": 3, "z": 25, "k": "v", "zu": [[200, "g", "Nüsslisalat"], [4, "", "Eier"], [150, "g", "Brot vom Vortag"], [1, "", "Schalotte"], [100, "g", "Bergkäse"]], "vo": ["Olivenöl", "Butter", "Essig", "Senf", "Salz", "Pfeffer"], "s": ["Eier 9 Min kochen, abschrecken, schälen und hacken.", "Brot in Würfel schneiden und in Butter goldbraun rösten.", "Schalotte fein hacken und mit Essig, Senf, Öl, Salz und Pfeffer verrühren.", "Nüsslisalat waschen und gut trocknen, Käse in Würfel schneiden.", "Salat mit der Sauce mischen, Eier, Käse und Croûtons darüber verteilen."]},
{"n": "Ofenkürbis mit Feta und Baumnüssen", "von": 9, "bis": 11, "z": 45, "k": "v", "zu": [[1, "kg", "Butternuss-Kürbis"], [2, "", "Rote Zwiebeln"], [200, "g", "Feta"], [50, "g", "Baumnüsse"], [150, "g", "Bulgur"], [1, "Bund", "Peterli"]], "vo": ["Olivenöl", "Honig", "Chili", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen. Kürbis in Spalten, Zwiebeln in Schnitze schneiden.", "Gemüse mit Öl, Salz und Chili mischen und auf dem Blech 30 Min backen.", "Bulgur in Salzwasser nach Packungsangabe garen.", "Baumnüsse grob hacken, Feta zerbröckeln und beides die letzten 5 Min mitbacken.", "Mit wenig Honig beträufeln, Peterli darüberstreuen und mit Bulgur servieren."]},
{"n": "Ofenlachs mit Orangen und Fenchel", "von": 12, "bis": 3, "z": 40, "k": "fi", "zu": [[450, "g", "Lachsfilet"], [2, "", "Fenchel"], [2, "", "Orangen"], [1, "", "Rote Zwiebel"], [240, "g", "Couscous"]], "vo": ["Olivenöl", "Honig", "Salz", "Pfeffer", "Chili"], "s": ["Ofen auf 200 °C vorheizen. Fenchel und Zwiebel in Spalten schneiden, mit Olivenöl und Salz auf ein Blech geben und 15 Min backen.", "Eine Orange in Scheiben schneiden, die andere auspressen.", "Lachs auf das Gemüse legen, Orangenscheiben darum verteilen, mit Orangensaft, Honig, Chili, Salz und Pfeffer beträufeln.", "Weitere 12–15 Min backen.", "Couscous mit heissem Salzwasser übergiessen, quellen lassen und dazu servieren."]},
{"n": "Ofenpoulet mit Rosenkohl", "von": 11, "bis": 2, "z": 55, "k": "f", "zu": [[6, "", "Pouletschenkel"], [500, "g", "Rosenkohl"], [600, "g", "Kartoffeln, festkochend"], [2, "", "Rote Zwiebeln"], [1, "", "Zitrone"]], "vo": ["Olivenöl", "Knoblauch", "Paprika", "Salz", "Pfeffer", "Honig"], "s": ["Ofen auf 200 °C vorheizen. Rosenkohl halbieren, Kartoffeln in Schnitze, Zwiebeln in Spalten schneiden.", "Gemüse mit Olivenöl, Salz und Pfeffer mischen und auf einem Blech verteilen.", "Pouletschenkel mit Öl, Knoblauch, Paprika, Honig und Salz einreiben und auf das Gemüse legen.", "45 Min backen, bis die Haut knusprig ist.", "Mit Zitronensaft beträufeln und servieren."]},
{"n": "Ofenpoulet mit Trauben", "von": 9, "bis": 10, "z": 60, "k": "f", "zu": [[6, "", "Pouletschenkel"], [400, "g", "Trauben, kernlos"], [2, "", "Rote Zwiebeln"], [600, "g", "Kartoffeln, festkochend"], [1, "dl", "Weisswein"], [0.5, "Bund", "Thymian"]], "vo": ["Olivenöl", "Knoblauch", "Honig", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen. Kartoffeln in Schnitze, Zwiebeln in Spalten schneiden.", "Pouletschenkel mit Salz, Pfeffer, Knoblauch und Öl einreiben.", "Kartoffeln, Zwiebeln und Thymian aufs Blech geben, Poulet darauflegen und 25 Min backen.", "Trauben und Wein dazugeben, Poulet mit wenig Honig bestreichen und weitere 20 Min backen.", "Mit dem Bratensaft beträufeln und servieren."]},
{"n": "Ofenpoulet mit neuen Kartoffeln", "von": 4, "bis": 6, "z": 60, "k": "f", "zu": [[6, "", "Pouletschenkel"], [800, "g", "Kartoffeln, neue"], [1, "Bund", "Frühlingszwiebeln"], [1, "", "Zitrone"], [1, "Bund", "Thymian"]], "vo": ["Olivenöl", "Knoblauch", "Paprika", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen.", "Kartoffeln halbieren, Frühlingszwiebeln in grosse Stücke schneiden, Zitrone in Schnitze.", "Alles mit Olivenöl, Knoblauch, Thymian, Salz und Pfeffer auf einem Blech mischen.", "Pouletschenkel mit Paprika und Salz würzen und darauflegen.", "45 Min backen, bis die Haut knusprig ist."]},
{"n": "Ofenranden mit Linsen und Chèvre", "von": 9, "bis": 12, "z": 60, "k": "v", "zu": [[600, "g", "Randen, roh"], [150, "g", "Beluga-Linsen"], [1, "", "Rote Zwiebel"], [150, "g", "Ziegenfrischkäse"], [40, "g", "Baumnüsse"], [100, "g", "Rucola"]], "vo": ["Olivenöl", "Essig", "Honig", "Senf", "Salz", "Pfeffer"], "s": ["Ofen auf 200 °C vorheizen. Randen schälen, in Schnitze schneiden, mit Öl und Salz mischen und 40 Min backen.", "Linsen in ungesalzenem Wasser 20 Min weich kochen und abgiessen.", "Zwiebel fein hacken. Essig, Öl, Senf, Honig, Salz und Pfeffer zu einer Sauce rühren und mit Linsen und Zwiebel mischen.", "Baumnüsse grob hacken und ohne Fett rösten.", "Linsen mit Rucola und Randen anrichten, Ziegenkäse darüberzupfen und Nüsse darüberstreuen."]},
{"n": "Orangen-Carpaccio mit Granatapfel", "von": 12, "bis": 3, "z": 15, "k": "vg", "zu": [[4, "", "Orangen"], [1, "", "Granatapfel"], [30, "g", "Pistazien, gehackt"], [1, "Bund", "Minze"]], "vo": ["Honig", "Zimt"], "s": ["Orangen grosszügig schälen, sodass die weisse Haut ganz entfernt ist.", "In dünne Scheiben schneiden und auf Tellern auslegen.", "Granatapfelkerne herauslösen und darüber verteilen.", "Mit wenig Honig beträufeln (vegan: Agavendicksaft) und mit Zimt bestäuben.", "Pistazien und gezupfte Minze darüberstreuen."]},
{"n": "Orecchiette mit Salsiccia", "von": 3, "bis": 5, "z": 25, "k": "f", "zu": [[350, "g", "Orecchiette"], [300, "g", "Salsiccia"], [300, "g", "Blattspinat"], [1, "", "Zwiebel"], [60, "g", "Pecorino"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Orecchiette in Salzwasser al dente kochen.", "Salsiccia aus der Haut drücken und in Olivenöl krümelig braten.", "Zwiebel, Knoblauch und Chili zugeben und mitdünsten.", "Spinat zugeben und zusammenfallen lassen.", "Pasta mit etwas Kochwasser untermischen und mit Pecorino servieren."]},
{"n": "Ossobuco mit Gremolata", "von": 11, "bis": 3, "z": 120, "k": "f", "zu": [[3, "", "Kalbshaxen in Scheiben"], [1, "", "Zwiebel"], [2, "", "Rüebli"], [1, "Dose", "Pelati"], [2, "dl", "Weisswein"], [1, "", "Zitrone, unbehandelt"], [1, "Bund", "Peterli"], [240, "g", "Risottoreis"]], "vo": ["Mehl", "Olivenöl", "Butter", "Knoblauch", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Haxen salzen, pfeffern, in Mehl wenden und in Olivenöl beidseitig anbraten, herausnehmen.", "Zwiebel und Rüebli würfeln, im Bratfett andünsten, mit Wein ablöschen und Pelati dazugeben.", "Haxen hineinlegen, zugedeckt 1.5 Std leise schmoren, ab und zu Bouillon nachgiessen.", "Risotto mit Bouillon in 18 Min cremig rühren, mit Butter verfeinern.", "Für die Gremolata Peterli, Zitronenschale und Knoblauch fein hacken und über das Fleisch streuen."]},
{"n": "Panzanella", "von": 7, "bis": 9, "z": 25, "k": "vg", "zu": [[250, "g", "Ciabatta vom Vortag"], [700, "g", "Tomaten"], [1, "", "Gurke"], [1, "", "Peperoni, gelb"], [1, "", "Zwiebel, rot"], [1, "EL", "Kapern"], [1, "Bund", "Basilikum"]], "vo": ["Olivenöl", "Essig", "Salz", "Pfeffer", "Knoblauch"], "s": ["Brot in Würfel schneiden und in Olivenöl mit Knoblauch knusprig rösten.", "Tomaten, Gurke und Peperoni würfeln, Zwiebel in feine Ringe schneiden.", "Gemüse mit Kapern, Olivenöl, Essig, Salz und Pfeffer mischen.", "Brotwürfel unterheben und 10 Min ziehen lassen, damit sie den Saft aufsaugen.", "Mit Basilikum bestreuen und servieren."]},
{"n": "Papet vaudois mit Saucisson", "von": 11, "bis": 3, "z": 75, "k": "f", "zu": [[1, "", "Saucisson vaudois, ca. 400 g"], [800, "g", "Lauch"], [500, "g", "Kartoffeln, mehligkochend"], [1, "dl", "Weisswein"], [0.5, "dl", "Rahm"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Lauch in Ringe schneiden, Kartoffeln schälen und würfeln.", "Lauch in Butter andünsten, Kartoffeln dazugeben, mit Wein und Bouillon knapp bedecken.", "Saucisson darauflegen und zugedeckt 45 Min leise köcheln.", "Saucisson herausnehmen, Gemüse mit Rahm verfeinern, etwas zerdrücken und abschmecken.", "Saucisson in dicke Scheiben schneiden und auf dem Papet servieren."]},
{"n": "Pasta alla Norma", "von": 7, "bis": 9, "z": 40, "k": "v", "zu": [[2, "", "Auberginen"], [350, "g", "Penne"], [1, "Dose", "Tomaten, gehackt"], [250, "g", "Cherrytomaten"], [80, "g", "Ricotta salata oder Pecorino"], [1, "Bund", "Basilikum"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Auberginen würfeln und in reichlich Olivenöl goldbraun braten, herausnehmen.", "Knoblauch und Chili andünsten, gehackte und halbierte Tomaten dazugeben und 15 Min köcheln.", "Penne in Salzwasser al dente kochen.", "Auberginen in die Sauce geben und mit der abgetropften Pasta mischen.", "Mit geriebenem Käse und Basilikum servieren."]},
{"n": "Pasta mit Birnen und Gorgonzola", "von": 9, "bis": 11, "z": 25, "k": "v", "zu": [[350, "g", "Tagliatelle"], [2, "", "Birnen"], [150, "g", "Gorgonzola"], [1, "dl", "Rahm"], [50, "g", "Baumnüsse"], [50, "g", "Rucola"]], "vo": ["Butter", "Pfeffer", "Salz"], "s": ["Pasta in Salzwasser al dente kochen.", "Birnen entkernen, in Schnitze schneiden und in Butter 3 Min braten.", "Gorgonzola in Rahm schmelzen lassen und mit Pfeffer würzen.", "Baumnüsse grob hacken und ohne Fett rösten.", "Pasta mit Sauce und Birnen mischen, mit Rucola und Nüssen anrichten."]},
{"n": "Pasta mit Thon und Kapern", "von": 1, "bis": 12, "z": 25, "k": "fi", "zu": [[350, "g", "Spaghetti"], [2, "Dose", "Thon in Öl"], [1, "Dose", "Tomaten, gehackt (400 g)"], [2, "EL", "Kapern"], [80, "g", "Oliven, schwarz"], [0.5, "Bund", "Peterli"]], "vo": ["Olivenöl", "Knoblauch", "Chili", "Salz", "Pfeffer"], "s": ["Spaghetti in Salzwasser al dente kochen.", "Knoblauch und Chili in Olivenöl andünsten.", "Tomaten zugeben und 10 Min köcheln.", "Thon zerpflücken und mit Kapern und Oliven in die Sauce geben, kurz erwärmen.", "Mit Spaghetti mischen und mit Peterli bestreuen."]},
{"n": "Pasta mit Zucchetti und Salsiccia", "von": 6, "bis": 9, "z": 30, "k": "f", "zu": [[350, "g", "Orecchiette oder Penne"], [3, "", "Salsicce"], [2, "", "Zucchetti"], [250, "g", "Cherrytomaten"], [50, "g", "Parmesan"], [0.5, "Bund", "Basilikum"]], "vo": ["Olivenöl", "Chili", "Salz", "Pfeffer", "Knoblauch"], "s": ["Pasta in Salzwasser al dente kochen.", "Salsiccia aus der Haut drücken und in Olivenöl krümelig anbraten.", "Zucchetti würfeln, mit Knoblauch und Chili dazugeben und 5 Min braten.", "Halbierte Tomaten kurz mitbraten, Pasta mit etwas Kochwasser untermischen.", "Mit Parmesan und Basilikum servieren."]},
{"n": "Pasta primavera", "von": 4, "bis": 6, "z": 25, "k": "v", "zu": [[350, "g", "Penne"], [250, "g", "Grüne Spargeln"], [150, "g", "Erbsen"], [150, "g", "Kefen"], [1, "", "Zucchetti"], [1, "", "Zitrone, unbehandelt"], [60, "g", "Parmesan"]], "vo": ["Olivenöl", "Knoblauch", "Butter", "Salz", "Pfeffer"], "s": ["Penne in Salzwasser al dente kochen.", "Spargeln und Zucchetti in Stücke schneiden, Kefen halbieren.", "Knoblauch in Olivenöl andünsten, Gemüse 5 Min mitbraten. Erbsen kurz mitwärmen.", "Penne mit etwas Kochwasser, Butter und abgeriebener Zitronenschale zum Gemüse geben.", "Parmesan unterziehen und mit Salz, Pfeffer und Zitronensaft abschmecken."]},
{"n": "Pastinakensuppe mit Ingwer", "von": 11, "bis": 3, "z": 35, "k": "vg", "zu": [[600, "g", "Pastinaken"], [1, "", "Zwiebel"], [1, "", "Apfel"], [20, "g", "Ingwer"], [2, "dl", "Kokosmilch"], [1, "Bund", "Schnittlauch"], [1, "", "Ruchbrot, klein"]], "vo": ["Rapsöl", "Gemüsebouillon", "Curry", "Salz", "Pfeffer"], "s": ["Pastinaken und Apfel schälen und würfeln, Zwiebel und Ingwer hacken.", "Alles in Öl andünsten, Curry kurz mitrösten.", "Mit Bouillon auffüllen, bis das Gemüse knapp bedeckt ist, und 20 Min köcheln.", "Kokosmilch dazugeben und fein pürieren, abschmecken.", "Mit Schnittlauch bestreuen und mit Brot servieren."]},
{"n": "Penne all'arrabbiata", "von": 1, "bis": 12, "z": 25, "k": "vg", "zu": [[350, "g", "Penne"], [2, "Dose", "Tomaten, gehackt"], [4, "Zehe", "Knoblauch"], [0.5, "Bund", "Peterli"]], "vo": ["Olivenöl", "Chili", "Salz", "Zucker", "Tomatenpüree"], "s": ["Knoblauch in Scheiben schneiden und mit Chili in Olivenöl sanft andünsten.", "Tomatenpüree kurz mitrösten, Tomaten dazugeben, mit Salz und wenig Zucker würzen und 15 Min köcheln.", "Penne in Salzwasser al dente kochen.", "Pasta abgiessen und in der Sauce schwenken.", "Mit gehacktem Peterli bestreuen und servieren."]},
{"n": "Penne mit Erbsen und Schinken", "von": 5, "bis": 6, "z": 25, "k": "f", "zu": [[350, "g", "Penne"], [150, "g", "Schinken, gekocht"], [250, "g", "Erbsen"], [2, "dl", "Halbrahm"], [3, "", "Frühlingszwiebeln"], [50, "g", "Parmesan"]], "vo": ["Butter", "Salz", "Pfeffer", "Muskat"], "s": ["Penne in Salzwasser al dente kochen.", "Schinken in Streifen, Frühlingszwiebeln in Ringe schneiden.", "Frühlingszwiebeln in Butter andünsten, Schinken kurz mitbraten.", "Erbsen und Rahm zugeben und 5 Min köcheln, mit Pfeffer und Muskat würzen.", "Penne untermischen und mit Parmesan servieren."]},
{"n": "Peperonata mit Polenta", "von": 7, "bis": 9, "z": 45, "k": "v", "zu": [[4, "", "Peperoni, rot und gelb"], [2, "", "Zwiebeln"], [400, "g", "Tomaten"], [200, "g", "Polenta, grob"], [60, "g", "Parmesan"], [1, "EL", "Kapern"]], "vo": ["Olivenöl", "Butter", "Gemüsebouillon", "Essig", "Salz", "Pfeffer", "Knoblauch"], "s": ["Peperoni und Zwiebeln in Streifen schneiden und in Olivenöl mit Knoblauch 10 Min dünsten.", "Gewürfelte Tomaten und Kapern dazugeben und zugedeckt 20 Min schmoren, mit Essig abschmecken.", "Bouillon aufkochen, Polenta einrühren und unter Rühren 20 Min köcheln.", "Butter und Parmesan unter die Polenta rühren.", "Polenta mit der Peperonata anrichten."]},
{"n": "Pilz-Stroganoff mit Reis", "von": 9, "bis": 11, "z": 30, "k": "v", "zu": [[600, "g", "Champignons"], [1, "", "Zwiebel"], [1, "", "Essiggurke"], [1.5, "dl", "Saucenhalbrahm"], [240, "g", "Langkornreis"], [0.5, "Bund", "Peterli"]], "vo": ["Butter", "Paprika", "Senf", "Tomatenpüree", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Reis nach Packungsangabe kochen.", "Champignons vierteln, Zwiebel fein hacken, Essiggurke in Streifen schneiden.", "Champignons portionenweise in Butter kräftig anbraten, Zwiebel kurz mitbraten.", "Paprika und Tomatenpüree dazugeben, mit wenig Bouillon ablöschen.", "Halbrahm, Senf und Gurken dazugeben und 5 Min köcheln. Abschmecken und mit Peterli und Reis servieren."]},
{"n": "Pilzrisotto", "von": 9, "bis": 11, "z": 40, "k": "v", "zu": [[400, "g", "Pilze, gemischt"], [10, "g", "Steinpilze, getrocknet"], [240, "g", "Risottoreis"], [1, "", "Zwiebel"], [1, "dl", "Weisswein"], [60, "g", "Parmesan"], [0.5, "Bund", "Peterli"]], "vo": ["Butter", "Olivenöl", "Knoblauch", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Getrocknete Steinpilze in heissem Wasser 10 Min einweichen, dann hacken. Einweichwasser zur Bouillon geben.", "Frische Pilze in Scheiben schneiden und mit Knoblauch in Öl kräftig anbraten, beiseitestellen.", "Zwiebel hacken und in Butter andünsten. Reis und Steinpilze 2 Min mitdünsten, mit Wein ablöschen.", "Nach und nach heisse Bouillon dazugeben und 18 Min rühren.", "Gebratene Pilze, Parmesan und etwas Butter unterrühren, abschmecken und mit Peterli bestreuen."]},
{"n": "Pilzschnitten", "von": 9, "bis": 11, "z": 25, "k": "v", "zu": [[500, "g", "Pilze, gemischt"], [1, "", "Schalotte"], [6, "", "Brotscheiben, Halbweiss"], [1, "dl", "Weisswein"], [1.5, "dl", "Rahm"], [1, "Bund", "Peterli"], [150, "g", "Nüsslisalat"]], "vo": ["Butter", "Knoblauch", "Essig", "Rapsöl", "Senf", "Salz", "Pfeffer"], "s": ["Pilze in Scheiben schneiden, Schalotte und Knoblauch fein hacken.", "Brotscheiben in Butter beidseitig goldbraun rösten.", "Pilze in Butter kräftig anbraten, Schalotte und Knoblauch kurz mitdünsten.", "Mit Wein ablöschen, Rahm dazugeben und einkochen, bis die Sauce sämig ist. Abschmecken und Peterli unterziehen.", "Pilze auf die Brote verteilen und mit Nüsslisalat an einer Senf-Vinaigrette servieren."]},
{"n": "Pizokel mit Wirz und Speck", "von": 10, "bis": 3, "z": 50, "k": "f", "zu": [[300, "g", "Mehl"], [3, "", "Eier"], [1.5, "dl", "Milch"], [400, "g", "Wirz"], [120, "g", "Speckwürfeli"], [1, "", "Zwiebel"], [100, "g", "Bergkäse"]], "vo": ["Butter", "Salz", "Pfeffer", "Muskat"], "s": ["Mehl, Eier, Milch und Salz zu einem zähen Teig klopfen und 15 Min ruhen lassen.", "Teig portionenweise auf einem Brett dünn ausstreichen und mit einem Messer Streifen ins siedende Salzwasser schaben. Aufschwimmende Pizokel abschöpfen.", "Wirz in Streifen schneiden und in Salzwasser 4 Min blanchieren.", "Zwiebel hacken und mit dem Speck in Butter anbraten, Wirz dazugeben und mitdünsten.", "Pizokel darunter mischen und braten, bis sie leicht knusprig sind. Mit Muskat würzen und geriebenen Käse darüberstreuen."]},
{"n": "Pizzoccheri mit Wirz", "von": 11, "bis": 2, "z": 40, "k": "v", "zu": [[300, "g", "Pizzoccheri (Buchweizennudeln)"], [300, "g", "Wirz"], [300, "g", "Kartoffeln, festkochend"], [150, "g", "Bergkäse, in Würfeln"], [50, "g", "Parmesan, gerieben"], [2, "Zehe", "Knoblauch"], [80, "g", "Butter"]], "vo": ["Salz", "Pfeffer"], "s": ["Kartoffeln schälen und würfeln, Wirz in Streifen schneiden.", "Kartoffeln in Salzwasser 5 Min kochen, Wirz und Pizzoccheri dazugeben und weitere 10 Min garen.", "Butter mit dem in Scheiben geschnittenen Knoblauch aufschäumen, bis sie nussig duftet.", "Alles abgiessen und lagenweise mit Bergkäse und Parmesan in eine Schüssel geben.", "Knoblauchbutter darübergiessen, pfeffern und sofort servieren."]},
{"n": "Poulet-Fajitas mit Peperoni", "von": 6, "bis": 9, "z": 35, "k": "f", "zu": [[450, "g", "Pouletbrust"], [3, "", "Peperoni, verschiedene Farben"], [1, "", "Zwiebel, rot"], [9, "", "Tortillas"], [1, "Becher", "Sauerrahm"], [1, "", "Avocado"], [1, "", "Limette"], [100, "g", "Cheddar, gerieben"]], "vo": ["Rapsöl", "Paprika", "Kreuzkümmel", "Chili", "Oregano", "Salz"], "s": ["Poulet, Peperoni und Zwiebel in Streifen schneiden.", "Poulet mit Öl, Gewürzen, Salz und Limettensaft mischen.", "Poulet in einer heissen Pfanne 5 Min anbraten, Gemüse dazugeben und weitere 5 Min braten.", "Avocado zerdrücken und mit Salz und Limette würzen, Tortillas kurz erwärmen.", "Alles mit Sauerrahm und Käse auf den Tisch stellen und selbst füllen lassen."]},
{"n": "Poulet-Satay mit Erdnusssauce", "von": 6, "bis": 9, "z": 45, "k": "f", "zu": [[450, "g", "Pouletbrust"], [4, "EL", "Erdnussbutter"], [1, "dl", "Kokosmilch"], [1, "", "Limette"], [1, "", "Gurke"], [240, "g", "Jasminreis"], [20, "g", "Ingwer"]], "vo": ["Sojasauce", "Honig", "Curry", "Chili", "Rapsöl", "Knoblauch"], "s": ["Poulet in Streifen schneiden und mit Sojasauce, Honig, Curry, geriebenem Ingwer und Knoblauch 20 Min marinieren.", "Fleisch wellenartig auf Spiesse stecken.", "Erdnussbutter mit Kokosmilch, Sojasauce, Limettensaft und Chili sanft erwärmen und glatt rühren.", "Spiesse auf dem Grill oder in der Grillpfanne 8–10 Min rundum grillieren, inzwischen Reis garen.", "Gurke in Scheiben schneiden und mit Spiessen, Sauce und Reis servieren."]},
{"n": "Poulet-Spargel-Wok", "von": 4, "bis": 6, "z": 30, "k": "f", "zu": [[400, "g", "Pouletbrust"], [400, "g", "Grüne Spargeln"], [1, "Bund", "Frühlingszwiebeln"], [1, "", "Ingwer, daumengross"], [240, "g", "Jasminreis"], [2, "EL", "Austernsauce"], [1, "EL", "Maisstärke"]], "vo": ["Rapsöl", "Knoblauch", "Sojasauce", "Chili"], "s": ["Reis nach Packungsangabe kochen.", "Poulet in Streifen schneiden, mit Sojasauce und Maisstärke mischen.", "Spargeln schräg in Stücke, Frühlingszwiebeln in Ringe schneiden, Ingwer und Knoblauch hacken.", "Poulet im sehr heissen Öl 3 Min braten, herausnehmen.", "Gemüse 3 Min pfannenrühren, Poulet, Austernsauce und Chili zugeben und mit Reis servieren."]},
{"n": "Pouletschenkel mit Maiskolben", "von": 7, "bis": 9, "z": 60, "k": "f", "zu": [[6, "", "Pouletschenkel"], [3, "", "Maiskolben"], [1, "", "Zitrone"], [500, "g", "Tomaten"], [1, "", "Zwiebel, rot"], [50, "g", "Butter"]], "vo": ["Olivenöl", "Paprika", "Honig", "Senf", "Salz", "Pfeffer", "Knoblauch"], "s": ["Olivenöl, Paprika, Honig, Senf, Knoblauch, Zitronensaft und Salz verrühren und die Pouletschenkel damit einreiben.", "Schenkel auf dem Grill bei indirekter Hitze oder bei 200 °C im Ofen 40 Min garen, dabei mehrmals wenden.", "Maiskolben 10 Min vorkochen, mit Butter bestreichen und rundum grillieren.", "Tomaten in Scheiben, Zwiebel in Ringe schneiden und mit Olivenöl, Salz und Pfeffer anmachen.", "Poulet mit Mais und Tomatensalat servieren."]},
{"n": "Pouletschnitzel mit Spargelsalat", "von": 4, "bis": 6, "z": 35, "k": "f", "zu": [[400, "g", "Pouletbrust"], [2, "", "Eier"], [80, "g", "Paniermehl"], [500, "g", "Grüne Spargeln"], [1, "Bund", "Radiesli"], [1, "", "Zitrone"]], "vo": ["Mehl", "Rapsöl", "Olivenöl", "Senf", "Honig", "Salz", "Pfeffer"], "s": ["Poulet in dünne Schnitzel schneiden und flach klopfen, würzen.", "Schnitzel in Mehl, verquirlten Eiern und Paniermehl wenden.", "Spargeln in Stücke schneiden und 4 Min in Salzwasser blanchieren, kalt abschrecken. Radiesli in Scheiben schneiden.", "Zitronensaft, Olivenöl, Senf und Honig verrühren und mit dem Gemüse mischen.", "Schnitzel im Rapsöl pro Seite 3 Min goldbraun braten und mit Salat und Zitronenschnitzen servieren."]},
{"n": "Raclette mit Gschwellti", "von": 11, "bis": 2, "z": 40, "k": "v", "zu": [[1, "kg", "Kartoffeln, festkochend, klein"], [600, "g", "Raclettekäse, in Scheiben"], [1, "Glas", "Cornichons"], [1, "Glas", "Silberzwiebeln"], [1, "", "Birne"]], "vo": ["Salz", "Pfeffer", "Paprika"], "s": ["Kartoffeln mit Schale in Salzwasser 20–25 Min weich kochen.", "Birne in Schnitze schneiden, Cornichons und Silberzwiebeln abtropfen lassen.", "Raclettegerät vorheizen.", "Käse in den Pfännchen schmelzen lassen, bis er Blasen wirft.", "Über die Kartoffeln streichen, mit Pfeffer und Paprika würzen und mit Beilagen essen."]},
{"n": "Randenrisotto mit Ziegenkäse", "von": 11, "bis": 3, "z": 40, "k": "v", "zu": [[300, "g", "Randen, gekocht"], [240, "g", "Risottoreis"], [1, "", "Zwiebel"], [1, "dl", "Rotwein"], [40, "g", "Parmesan, gerieben"], [120, "g", "Ziegenfrischkäse"], [40, "g", "Baumnüsse"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Randen in kleine Würfel schneiden, Zwiebel fein hacken.", "Zwiebel in Butter andünsten, Reis 2 Min mitdünsten.", "Mit Rotwein ablöschen, nach und nach heisse Bouillon dazugeben und 18 Min rühren.", "Randen die letzten 5 Min mitgaren, Parmesan und etwas Butter unterrühren.", "Abschmecken, mit Ziegenkäse und gehackten Baumnüssen anrichten."]},
{"n": "Ratatouille mit Reis", "von": 7, "bis": 9, "z": 60, "k": "vg", "zu": [[1, "", "Aubergine"], [2, "", "Zucchetti"], [2, "", "Peperoni, rot und gelb"], [500, "g", "Tomaten"], [1, "", "Zwiebel"], [3, "Zehe", "Knoblauch"], [240, "g", "Langkornreis"], [0.5, "Bund", "Basilikum"]], "vo": ["Olivenöl", "Salz", "Pfeffer", "Oregano", "Tomatenpüree"], "s": ["Aubergine, Zucchetti und Peperoni in Würfel schneiden, Zwiebel und Knoblauch hacken.", "Auberginen in Olivenöl anbraten und herausnehmen, dann Zwiebel, Knoblauch und Peperoni andünsten.", "Zucchetti, gewürfelte Tomaten, Tomatenpüree und Auberginen dazugeben, würzen und zugedeckt 30 Min schmoren.", "Inzwischen den Reis in Salzwasser garen.", "Ratatouille abschmecken, Basilikum darüberzupfen und mit dem Reis servieren."]},
{"n": "Rehpfeffer mit Spätzli", "von": 9, "bis": 11, "z": 150, "k": "f", "zu": [[500, "g", "Rehragout"], [5, "dl", "Rotwein, kräftig"], [2, "", "Rüebli"], [1, "", "Zwiebel"], [100, "g", "Knollensellerie"], [80, "g", "Speckwürfeli"], [150, "g", "Champignons"], [500, "g", "Spätzli, frisch"], [150, "g", "Rotkraut, gekocht"]], "vo": ["Rapsöl", "Mehl", "Tomatenpüree", "Gemüsebouillon", "Gewürze (Lorbeer, Wacholder)", "Butter", "Salz", "Pfeffer"], "s": ["Rüebli, Zwiebel und Sellerie würfeln. Fleisch salzen, mit Mehl bestäuben und portionenweise in Öl kräftig anbraten.", "Gemüse und Tomatenpüree kurz mitrösten, mit Rotwein ablöschen. Lorbeer und Wacholder dazugeben.", "Zugedeckt bei kleiner Hitze 2 Std schmoren, bei Bedarf etwas Bouillon nachgiessen.", "Speck und Champignons in einer Pfanne braten und kurz vor dem Servieren unter das Ragout ziehen.", "Spätzli in Butter goldbraun braten, Rotkraut erwärmen und alles zusammen anrichten."]},
{"n": "Rhabarberwähe", "von": 4, "bis": 6, "z": 65, "k": "v", "zu": [[1, "Packung", "Kuchenteig, rund"], [600, "g", "Rhabarber"], [3, "EL", "Gemahlene Haselnüsse"], [2, "", "Eier"], [2, "dl", "Halbrahm"], [80, "g", "Zucker"], [1, "Packung", "Vanillezucker"], [1, "EL", "Puderzucker"]], "vo": [], "s": ["Ofen auf 200 °C vorheizen. Teig in eine Wähenform legen, einstechen und mit Haselnüssen bestreuen.", "Rhabarber rüsten und in kleine Stücke schneiden, auf dem Teig verteilen.", "Im unteren Teil des Ofens 15 Min vorbacken.", "Eier, Rahm, Zucker und Vanillezucker verquirlen und über den Rhabarber giessen.", "Weitere 25 Min backen, etwas abkühlen lassen und mit Puderzucker bestäuben."]},
{"n": "Rindfleisch mit Kefen aus dem Wok", "von": 5, "bis": 7, "z": 30, "k": "f", "zu": [[400, "g", "Rindshuft"], [300, "g", "Kefen"], [1, "Bund", "Frühlingszwiebeln"], [1, "", "Ingwer, daumengross"], [240, "g", "Jasminreis"], [2, "EL", "Hoisinsauce"], [1, "EL", "Maisstärke"]], "vo": ["Rapsöl", "Knoblauch", "Sojasauce", "Chili"], "s": ["Reis nach Packungsangabe kochen.", "Fleisch in feine Streifen schneiden und mit Sojasauce und Maisstärke mischen.", "Ingwer und Knoblauch hacken, Frühlingszwiebeln in Stücke schneiden.", "Fleisch im sehr heissen Öl 2 Min braten, herausnehmen.", "Kefen und Gewürze 3 Min pfannenrühren, Fleisch und Hoisinsauce zugeben und mit Reis servieren."]},
{"n": "Rindsgulasch", "von": 1, "bis": 12, "z": 135, "k": "f", "zu": [[600, "g", "Rindsragout"], [500, "g", "Zwiebeln"], [1, "", "Peperoni, rot"], [2, "dl", "Rotwein"], [300, "g", "Nudeln oder Spätzli"], [1, "Becher", "Sauerrahm"]], "vo": ["Rapsöl", "Paprika", "Kreuzkümmel", "Tomatenpüree", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Zwiebeln in Streifen schneiden, Peperoni würfeln.", "Fleisch portionenweise in Öl kräftig anbraten, herausnehmen.", "Zwiebeln im Bratfett 10 Min goldbraun dünsten, Tomatenpüree, Paprika und Kreuzkümmel kurz mitrösten.", "Fleisch und Peperoni dazugeben, mit Rotwein und Bouillon ablöschen und zugedeckt 1.5 Std schmoren.", "Nudeln kochen und mit dem Gulasch und Sauerrahm servieren."]},
{"n": "Rindsschmorbraten in Rotwein", "von": 11, "bis": 3, "z": 180, "k": "f", "zu": [[800, "g", "Rindsschulter oder Schmorbraten"], [2, "", "Zwiebeln"], [2, "", "Rüebli"], [0.25, "", "Knollensellerie"], [5, "dl", "Rotwein"], [300, "g", "Polenta"]], "vo": ["Rapsöl", "Tomatenpüree", "Mehl", "Gemüsebouillon", "Salz", "Pfeffer", "Butter"], "s": ["Ofen auf 160 °C vorheizen. Fleisch salzen, pfeffern und im Bräter rundum kräftig anbraten, herausnehmen.", "Gemüse würfeln und im Bratfett anrösten, Tomatenpüree und etwas Mehl kurz mitrösten.", "Mit Rotwein ablöschen, Fleisch zurückgeben und mit Bouillon knapp zur Hälfte bedecken.", "Zugedeckt im Ofen 2.5 Std schmoren, ab und zu wenden.", "Polenta nach Packungsangabe kochen und mit Butter verfeinern.", "Fleisch in Scheiben schneiden, Sauce pürieren oder durchsieben und mit der Polenta servieren."]},
{"n": "Risotto mit Erbsen und Speck", "von": 5, "bis": 6, "z": 35, "k": "f", "zu": [[240, "g", "Risottoreis"], [1, "", "Zwiebel"], [100, "g", "Speckwürfeli"], [250, "g", "Erbsen"], [1, "dl", "Weisswein"], [60, "g", "Parmesan"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Speck in einer Pfanne knusprig braten, einen Teil für die Garnitur beiseitelegen.", "Zwiebel hacken und zum Speck geben, Reis 2 Min mitdünsten.", "Mit Wein ablöschen, nach und nach heisse Bouillon zugeben und 18 Min rühren.", "Nach 13 Min die Erbsen zugeben.", "Parmesan und Butter unterziehen, abschmecken und mit Speck bestreuen."]},
{"n": "Rosenkohl-Kartoffel-Gratin", "von": 11, "bis": 2, "z": 60, "k": "v", "zu": [[500, "g", "Rosenkohl"], [600, "g", "Kartoffeln, festkochend"], [2.5, "dl", "Rahm"], [1, "dl", "Milch"], [100, "g", "Greyerzer, gerieben"]], "vo": ["Butter", "Salz", "Pfeffer", "Muskat", "Knoblauch"], "s": ["Ofen auf 200 °C vorheizen. Rosenkohl rüsten und halbieren, Kartoffeln in Scheiben schneiden.", "Rosenkohl 5 Min in Salzwasser vorkochen, abtropfen lassen.", "Kartoffeln und Rosenkohl in eine gebutterte Gratinform schichten.", "Rahm, Milch, gepressten Knoblauch, Salz, Pfeffer und Muskat verrühren und darübergiessen.", "Käse darüberstreuen und 40 Min goldbraun backen."]},
{"n": "Rote-Linsen-Dal", "von": 1, "bis": 12, "z": 35, "k": "vg", "zu": [[250, "g", "Rote Linsen"], [1, "Dose", "Kokosmilch"], [1, "Dose", "Tomaten, gehackt (400 g)"], [1, "", "Zwiebel"], [1, "", "Ingwer, daumengross"], [240, "g", "Basmatireis"], [0.5, "Bund", "Koriander"]], "vo": ["Rapsöl", "Knoblauch", "Curry", "Kurkuma", "Kreuzkümmel", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Zwiebel, Knoblauch und Ingwer hacken und in Öl andünsten, Gewürze kurz mitrösten.", "Linsen, Tomaten, Kokosmilch und Wasser zugeben.", "Unter gelegentlichem Rühren 20 Min köcheln, bis die Linsen zerfallen.", "Mit Salz abschmecken, mit Koriander bestreuen und mit Reis servieren."]},
{"n": "Rotkraut mit Marroni und Spätzli", "von": 11, "bis": 1, "z": 60, "k": "v", "zu": [[600, "g", "Rotkraut"], [2, "", "Äpfel"], [1, "", "Zwiebel"], [1, "dl", "Rotwein"], [200, "g", "Marroni, geschält"], [500, "g", "Spätzli"]], "vo": ["Butter", "Zucker", "Essig", "Gemüsebouillon", "Zimt", "Salz", "Pfeffer"], "s": ["Rotkraut fein hobeln, Zwiebel hacken, Äpfel in Würfel schneiden.", "Zwiebel in Butter andünsten, Zucker darin leicht karamellisieren.", "Rotkraut und Äpfel dazugeben, mit Rotwein, Essig und etwas Bouillon ablöschen, mit Zimt würzen.", "Zugedeckt 40 Min schmoren, Marroni die letzten 10 Min mitgaren.", "Spätzli in Butter goldbraun braten und zum Rotkraut servieren."]},
{"n": "Räucherforelle auf Nüsslisalat", "von": 11, "bis": 3, "z": 30, "k": "fi", "zu": [[300, "g", "Räucherforellenfilets"], [150, "g", "Nüsslisalat"], [700, "g", "Kartoffeln, festkochend, klein"], [1, "Becher", "Crème fraîche"], [1, "Glas", "Meerrettich"], [1, "", "Apfel"]], "vo": ["Olivenöl", "Essig", "Senf", "Honig", "Salz", "Pfeffer"], "s": ["Kartoffeln in der Schale 20 Min kochen und halbieren.", "Crème fraîche mit etwas Meerrettich, Salz und Pfeffer verrühren.", "Essig, Senf, Honig und Öl zu einer Sauce verrühren, Apfel in feine Schnitze schneiden.", "Nüsslisalat und Apfel mit der Sauce mischen und anrichten.", "Forelle in Stücke zupfen, mit den warmen Kartoffeln und der Meerrettichcreme dazu servieren."]},
{"n": "Saibling auf Sellerie-Apfel-Püree", "von": 9, "bis": 11, "z": 45, "k": "fi", "zu": [[450, "g", "Saiblingsfilets"], [500, "g", "Knollensellerie"], [300, "g", "Kartoffeln, mehligkochend"], [2, "", "Äpfel"], [1, "dl", "Rahm"], [40, "g", "Baumnüsse"]], "vo": ["Butter", "Muskat", "Salz", "Pfeffer"], "s": ["Sellerie und Kartoffeln schälen, würfeln und in Salzwasser 20 Min weich kochen.", "Einen Apfel würfeln und die letzten 5 Min mitkochen. Abgiessen und mit Rahm und Butter fein pürieren, mit Muskat würzen.", "Den zweiten Apfel in Schnitze schneiden und in Butter goldbraun braten.", "Saibling würzen und auf der Hautseite 3 Min knusprig braten, wenden und 1 Min fertig braten.", "Fisch auf dem Püree anrichten, mit Apfelschnitzen und gehackten Baumnüssen servieren."]},
{"n": "Salade niçoise", "von": 6, "bis": 9, "z": 35, "k": "fi", "zu": [[500, "g", "Kartoffeln, festkochend"], [250, "g", "Grüne Bohnen"], [3, "", "Eier"], [2, "Dose", "Thunfisch"], [300, "g", "Tomaten"], [1, "", "Kopfsalat"], [80, "g", "Schwarze Oliven"], [1, "Dose", "Sardellenfilets"]], "vo": ["Olivenöl", "Essig", "Senf", "Salz", "Pfeffer", "Knoblauch"], "s": ["Kartoffeln in der Schale weich kochen, Bohnen 7 Min in Salzwasser garen, Eier 8 Min kochen.", "Olivenöl, Essig, Senf, Knoblauch, Salz und Pfeffer zu einer Sauce rühren.", "Salat zupfen, Kartoffeln in Scheiben, Tomaten und Eier in Schnitze schneiden.", "Alles mit Bohnen, Thunfisch und Oliven auf Tellern anrichten.", "Mit Sardellen belegen und mit der Sauce beträufeln."]},
{"n": "Sauerkraut mit Rippli", "von": 11, "bis": 2, "z": 90, "k": "f", "zu": [[600, "g", "Sauerkraut, roh"], [500, "g", "Rippli, geräuchert"], [3, "", "Wienerli"], [1, "", "Zwiebel"], [2, "dl", "Weisswein"], [800, "g", "Kartoffeln, festkochend"]], "vo": ["Rapsöl", "Gemüsebouillon", "Salz", "Pfeffer", "Senf"], "s": ["Zwiebel in Streifen schneiden und in Öl andünsten.", "Sauerkraut dazugeben, mit Wein und etwas Bouillon ablöschen.", "Rippli darauflegen und zugedeckt 60 Min leise köcheln.", "Kartoffeln schälen und in Salzwasser 20 Min kochen, Wienerli die letzten 10 Min aufs Sauerkraut legen.", "Fleisch aufschneiden und mit Sauerkraut, Kartoffeln und Senf servieren."]},
{"n": "Schnitz und drunder", "von": 10, "bis": 2, "z": 90, "k": "f", "zu": [[150, "g", "Apfel- und Birnenschnitze, gedörrt"], [400, "g", "Rauchspeck, am Stück"], [700, "g", "Kartoffeln, festkochend"], [1, "", "Zwiebel"]], "vo": ["Butter", "Zucker", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Dörrschnitze 1 Std in warmem Wasser einweichen.", "Zucker in Butter hellbraun schmelzen, gehackte Zwiebel kurz darin andünsten.", "Schnitze samt Einweichwasser und Speck dazugeben und zugedeckt 30 Min köcheln.", "Kartoffeln schälen, in Stücke schneiden, darauflegen, würzen und weitere 25 Min garen.", "Speck in Scheiben schneiden und mit Schnitzen und Kartoffeln servieren."]},
{"n": "Schnitzel mit Pilzrahmsauce", "von": 9, "bis": 11, "z": 35, "k": "f", "zu": [[450, "g", "Schweinsschnitzel"], [300, "g", "Champignons"], [1, "", "Schalotte"], [1, "dl", "Weisswein"], [2, "dl", "Rahm"], [300, "g", "Nudeln"], [0.5, "Bund", "Peterli"]], "vo": ["Rapsöl", "Butter", "Mehl", "Paprika", "Salz", "Pfeffer"], "s": ["Nudeln in Salzwasser al dente kochen.", "Schnitzel mit Salz, Pfeffer und Paprika würzen, mit Mehl bestäuben und beidseitig 2 Min braten. Warm stellen.", "Champignons in Scheiben schneiden und mit der gehackten Schalotte in Butter anbraten.", "Mit Wein ablöschen, Rahm dazugeben und einkochen, bis die Sauce sämig ist.", "Abschmecken, Peterli unterziehen und über die Schnitzel geben. Mit Nudeln servieren."]},
{"n": "Schoggifondue mit Früchten", "von": 11, "bis": 2, "z": 20, "k": "v", "zu": [[200, "g", "Dunkle Schokolade"], [1.5, "dl", "Rahm"], [2, "", "Orangen"], [2, "", "Bananen"], [2, "", "Birnen"], [100, "g", "Lebkuchen oder Biskuits"]], "vo": ["Zimt"], "s": ["Früchte schälen und in mundgerechte Stücke schneiden, Lebkuchen würfeln.", "Rahm im Caquelon erwärmen, nicht kochen.", "Schokolade grob hacken und im Rahm unter Rühren schmelzen lassen, mit Zimt würzen.", "Auf dem Rechaud bei kleiner Hitze warm halten.", "Früchte und Lebkuchen auf Gabeln eintauchen."]},
{"n": "Schupfnudeln mit Sauerkraut", "von": 11, "bis": 2, "z": 30, "k": "v", "zu": [[500, "g", "Schupfnudeln"], [500, "g", "Sauerkraut, gekocht"], [1, "", "Zwiebel"], [1, "", "Apfel"], [1, "dl", "Weisswein"], [1, "Becher", "Sauerrahm"]], "vo": ["Butter", "Salz", "Pfeffer", "Paprika"], "s": ["Zwiebel in Streifen schneiden, Apfel würfeln.", "Zwiebel in Butter andünsten, Apfel und Sauerkraut dazugeben, mit Wein ablöschen und 10 Min köcheln.", "Schupfnudeln in einer zweiten Pfanne in Butter rundum goldbraun braten.", "Sauerkraut unter die Schupfnudeln mischen und mit Pfeffer abschmecken.", "Mit Sauerrahm und etwas Paprika servieren."]},
{"n": "Schwarzwurzeln an Rahmsauce", "von": 11, "bis": 2, "z": 50, "k": "v", "zu": [[800, "g", "Schwarzwurzeln"], [1, "", "Zitrone"], [2, "dl", "Rahm"], [600, "g", "Kartoffeln, festkochend"], [1, "Bund", "Peterli"], [60, "g", "Bergkäse, gerieben"]], "vo": ["Butter", "Mehl", "Gemüsebouillon", "Salz", "Pfeffer", "Muskat"], "s": ["Schwarzwurzeln unter fliessendem Wasser schälen (Handschuhe tragen), in Stücke schneiden und sofort in Zitronenwasser legen.", "Kartoffeln in Salzwasser 20 Min kochen.", "Schwarzwurzeln in Bouillon 15 Min weich kochen, etwas Kochwasser auffangen.", "Butter schmelzen, Mehl darin anschwitzen, mit Kochwasser und Rahm ablöschen und 5 Min köcheln.", "Schwarzwurzeln in die Sauce geben, mit Muskat und Käse abschmecken, Peterli darüber und mit den Kartoffeln servieren."]},
{"n": "Schweinsfilet mit Rhabarberchutney", "von": 4, "bis": 6, "z": 45, "k": "f", "zu": [[450, "g", "Schweinsfilet"], [300, "g", "Rhabarber"], [1, "", "Zwiebel, rot"], [1, "", "Ingwer, klein"], [800, "g", "Kartoffeln, neue"]], "vo": ["Rapsöl", "Zucker", "Essig", "Salz", "Pfeffer", "Zimt"], "s": ["Ofen auf 80 °C vorheizen. Kartoffeln in der Schale weich kochen.", "Zwiebel und Ingwer hacken und andünsten. Rhabarber in Stücke schneiden und mit Zucker, Essig und Zimt zugeben.", "10 Min einkochen, bis das Chutney dickflüssig ist, abschmecken.", "Filet würzen, rundum 5 Min anbraten und im Ofen 30 Min fertig garen.", "Filet in Tranchen schneiden und mit Chutney und Kartoffeln servieren."]},
{"n": "Schweinsfilet mit Zwetschgen", "von": 8, "bis": 10, "z": 40, "k": "f", "zu": [[500, "g", "Schweinsfilet"], [300, "g", "Zwetschgen"], [1, "", "Schalotte"], [1, "dl", "Rotwein"], [1, "dl", "Halbrahm"], [250, "g", "Polenta"]], "vo": ["Rapsöl", "Butter", "Gemüsebouillon", "Zimt", "Honig", "Salz", "Pfeffer"], "s": ["Ofen auf 80 °C vorheizen. Filet würzen, rundum 5 Min anbraten und im Ofen 25 Min nachgaren.", "Polenta nach Packungsangabe in Bouillon kochen und mit Butter verfeinern.", "Zwetschgen entsteinen und vierteln. Schalotte hacken und in Butter andünsten.", "Zwetschgen, Rotwein, Zimt und Honig dazugeben und 5 Min köcheln, dann Halbrahm unterrühren.", "Filet in Scheiben schneiden und mit Zwetschgensauce und Polenta servieren."]},
{"n": "Schweinskoteletts mit Speckbohnen", "von": 7, "bis": 9, "z": 40, "k": "f", "zu": [[3, "", "Schweinskoteletts"], [500, "g", "Grüne Bohnen"], [80, "g", "Speckwürfel"], [1, "", "Zwiebel"], [600, "g", "Frühkartoffeln"], [0.5, "Bund", "Bohnenkraut oder Peterli"]], "vo": ["Rapsöl", "Butter", "Senf", "Paprika", "Salz", "Pfeffer"], "s": ["Kartoffeln in der Schale 20 Min kochen, dann halbieren und in Butter anbraten.", "Bohnen in Salzwasser 8 Min knapp weich kochen und kalt abschrecken.", "Speck und gehackte Zwiebel anbraten, Bohnen und Kräuter dazugeben und schwenken.", "Koteletts mit Senf, Paprika, Salz und Pfeffer würzen und auf dem Grill oder in der Pfanne je 4 Min pro Seite braten.", "Kurz ruhen lassen und mit Bohnen und Kartoffeln servieren."]},
{"n": "Schweizer Wurstsalat mit Käse", "von": 6, "bis": 8, "z": 25, "k": "f", "zu": [[4, "", "Cervelats"], [200, "g", "Emmentaler"], [1, "", "Zwiebel"], [4, "", "Essiggurken"], [1, "Bund", "Schnittlauch"], [2, "", "Tomaten"], [1, "", "Bauernbrot"]], "vo": ["Essig", "Rapsöl", "Senf", "Salz", "Pfeffer"], "s": ["Cervelats schälen, längs halbieren und in Scheiben schneiden.", "Käse in Streifen, Zwiebel in feine Ringe und Essiggurken in Scheiben schneiden.", "Essig, Öl, Senf, Salz und Pfeffer zu einer Sauce verrühren.", "Alles mit der Sauce mischen und 15 Min ziehen lassen.", "Mit Tomatenschnitzen, Schnittlauch und Brot servieren."]},
{"n": "Seelachs-Lauch-Gratin", "von": 11, "bis": 3, "z": 50, "k": "fi", "zu": [[450, "g", "Seelachsfilet"], [600, "g", "Lauch"], [600, "g", "Kartoffeln, festkochend"], [2, "dl", "Halbrahm"], [80, "g", "Greyerzer, gerieben"], [1, "", "Zitrone"]], "vo": ["Butter", "Salz", "Pfeffer", "Senf", "Muskat"], "s": ["Ofen auf 200 °C vorheizen. Kartoffeln in Scheiben schneiden und 8 Min in Salzwasser vorkochen.", "Lauch in Ringe schneiden und in Butter 5 Min andünsten.", "Kartoffeln und Lauch in eine Gratinform geben, Fisch in Stücken darauflegen, salzen und mit Zitronensaft beträufeln.", "Rahm mit Senf, Muskat und Pfeffer verrühren und darübergiessen.", "Mit Käse bestreuen und 25 Min backen."]},
{"n": "Selleriesteaks mit Kartoffelsalat", "von": 11, "bis": 3, "z": 45, "k": "v", "zu": [[1, "", "Knollensellerie, ca. 800 g"], [2, "", "Eier"], [80, "g", "Paniermehl"], [600, "g", "Kartoffeln, festkochend"], [1, "", "Zwiebel"], [1, "", "Zitrone"]], "vo": ["Mehl", "Rapsöl", "Gemüsebouillon", "Essig", "Senf", "Salz", "Pfeffer"], "s": ["Kartoffeln in der Schale 20 Min kochen, schälen und in Scheiben schneiden.", "Zwiebel fein hacken, mit heisser Bouillon, Essig, Senf und Öl verrühren und über die Kartoffeln giessen.", "Sellerie schälen, in fingerdicke Scheiben schneiden und in Salzwasser 5 Min vorkochen.", "Scheiben salzen, nacheinander in Mehl, verquirltem Ei und Paniermehl wenden.", "In Öl beidseitig je 3–4 Min goldbraun braten, mit Zitronenschnitzen servieren."]},
{"n": "Shakshuka mit Peperoni", "von": 7, "bis": 9, "z": 35, "k": "v", "zu": [[2, "", "Peperoni, rot"], [1, "", "Zwiebel"], [600, "g", "Tomaten"], [6, "", "Eier"], [100, "g", "Feta"], [0.5, "Bund", "Peterli"], [1, "", "Fladenbrot"]], "vo": ["Olivenöl", "Kreuzkümmel", "Paprika", "Chili", "Salz", "Knoblauch"], "s": ["Zwiebel und Peperoni in Streifen schneiden und in Olivenöl weich dünsten.", "Knoblauch und Gewürze kurz mitdünsten, gewürfelte Tomaten dazugeben und 15 Min einköcheln.", "Mit einem Löffel Mulden formen und die Eier hineingleiten lassen.", "Zugedeckt 6–8 Min stocken lassen, bis das Eiweiss fest ist.", "Mit Feta und Peterli bestreuen und mit Fladenbrot servieren."]},
{"n": "Siedfleisch mit Wintergemüse", "von": 11, "bis": 3, "z": 180, "k": "f", "zu": [[800, "g", "Siedfleisch vom Rind"], [1, "", "Lauch"], [3, "", "Rüebli"], [0.5, "", "Knollensellerie"], [1, "", "Zwiebel"], [600, "g", "Kartoffeln, festkochend"], [1, "Glas", "Meerrettich"]], "vo": ["Salz", "Pfeffer", "Lorbeer", "Nelken", "Senf", "Gemüsebouillon"], "s": ["Zwiebel halbieren, mit Lorbeer und Nelken bestecken und in einer Pfanne ohne Fett anrösten.", "Wasser mit Bouillon aufkochen, Fleisch und Zwiebel hineinlegen und 2.5 Std leise ziehen lassen, Schaum abschöpfen.", "Gemüse in grosse Stücke schneiden und die letzten 30 Min mitgaren.", "Kartoffeln schälen und separat in Salzwasser kochen.", "Fleisch in Scheiben schneiden und mit Gemüse, etwas Brühe, Senf und Meerrettich servieren."]},
{"n": "Spaghetti Bolognese", "von": 1, "bis": 12, "z": 70, "k": "f", "zu": [[350, "g", "Spaghetti"], [400, "g", "Rindshackfleisch"], [1, "", "Zwiebel"], [1, "", "Rüebli"], [1, "", "Stangensellerie"], [1, "Dose", "Tomaten, gehackt (400 g)"], [1, "dl", "Rotwein"], [50, "g", "Parmesan"]], "vo": ["Olivenöl", "Knoblauch", "Tomatenpüree", "Oregano", "Salz", "Pfeffer"], "s": ["Zwiebel, Rüebli, Sellerie und Knoblauch fein würfeln und in Olivenöl andünsten.", "Hackfleisch zugeben und krümelig anbraten, Tomatenpüree kurz mitrösten.", "Mit Wein ablöschen, Tomaten und Oregano zugeben und zugedeckt 45 Min köcheln.", "Spaghetti in Salzwasser al dente kochen.", "Sauce abschmecken, mit Spaghetti und Parmesan servieren."]},
{"n": "Spaghetti Carbonara", "von": 1, "bis": 12, "z": 25, "k": "f", "zu": [[350, "g", "Spaghetti"], [150, "g", "Guanciale oder Speck"], [4, "", "Eier (Eigelb)"], [1, "", "Ei"], [70, "g", "Pecorino oder Parmesan"]], "vo": ["Salz", "Pfeffer"], "s": ["Spaghetti in Salzwasser al dente kochen.", "Guanciale in Streifen schneiden und ohne Fett knusprig braten.", "Eigelb, Ei und geriebenen Käse mit viel Pfeffer verrühren.", "Spaghetti mit etwas Kochwasser zum Guanciale geben, Pfanne vom Herd nehmen.", "Eimasse rasch unterrühren, bis eine cremige Sauce entsteht. Sofort servieren."]},
{"n": "Spaghetti mit Bärlauchpesto", "von": 3, "bis": 4, "z": 20, "k": "v", "zu": [[350, "g", "Spaghetti"], [1, "Bund", "Bärlauch"], [50, "g", "Pinienkerne"], [60, "g", "Parmesan"], [1, "dl", "Olivenöl"], [150, "g", "Cherrytomaten"]], "vo": ["Salz", "Pfeffer"], "s": ["Spaghetti in Salzwasser al dente kochen.", "Pinienkerne ohne Fett goldbraun rösten.", "Bärlauch grob schneiden und mit Pinienkernen, Parmesan und Olivenöl fein pürieren, salzen.", "Tomaten halbieren.", "Spaghetti abgiessen, etwas Kochwasser aufbewahren. Mit Pesto und wenig Kochwasser mischen, Tomaten darüber."]},
{"n": "Spargeln mit Rohschinken", "von": 4, "bis": 6, "z": 40, "k": "f", "zu": [[1.5, "kg", "Weisse Spargeln"], [800, "g", "Kartoffeln, neue"], [150, "g", "Rohschinken"], [80, "g", "Butter"], [0.5, "Bund", "Peterli"]], "vo": ["Salz", "Zucker", "Pfeffer"], "s": ["Spargeln schälen und die Enden abschneiden. Kartoffeln in der Schale weich kochen.", "Spargeln in Salzwasser mit wenig Zucker 12–15 Min garen.", "Butter in einer Pfanne schmelzen, bis sie leicht braun ist und nussig duftet.", "Peterli fein hacken.", "Spargeln mit Kartoffeln und Rohschinken anrichten, braune Butter darüberträufeln und Peterli darüberstreuen."]},
{"n": "Spargeln mit Sauce hollandaise", "von": 4, "bis": 6, "z": 45, "k": "v", "zu": [[1.5, "kg", "Weisse Spargeln"], [750, "g", "Kartoffeln, neue"], [3, "", "Eier (Eigelb)"], [150, "g", "Butter"], [1, "", "Zitrone"], [0.5, "Bund", "Schnittlauch"]], "vo": ["Salz", "Zucker", "Pfeffer"], "s": ["Spargeln schälen und die holzigen Enden abschneiden. Kartoffeln in der Schale weich kochen.", "Spargeln in Salzwasser mit einer Prise Zucker 12–15 Min garen.", "Butter schmelzen. Eigelb mit etwas Zitronensaft und Wasser über dem heissen Wasserbad schaumig schlagen.", "Flüssige Butter langsam unterschlagen, bis die Sauce cremig ist. Mit Salz, Pfeffer und Zitrone abschmecken.", "Spargeln mit Kartoffeln anrichten, Sauce darübergiessen, Schnittlauch darüberstreuen."]},
{"n": "Spargelquiche", "von": 4, "bis": 6, "z": 60, "k": "v", "zu": [[1, "Packung", "Kuchenteig, rund"], [500, "g", "Grüne Spargeln"], [3, "", "Eier"], [2, "dl", "Halbrahm"], [100, "g", "Gruyère, gerieben"], [3, "", "Frühlingszwiebeln"]], "vo": ["Salz", "Pfeffer", "Muskat"], "s": ["Ofen auf 200 °C vorheizen. Teig mit dem Papier in eine Wähenform legen und mit einer Gabel einstechen.", "Spargelenden abschneiden, Spargeln in Stücke schneiden, Frühlingszwiebeln in Ringe schneiden.", "Gemüse auf dem Teig verteilen und mit Käse bestreuen.", "Eier mit Rahm verquirlen, mit Salz, Pfeffer und Muskat würzen und darübergiessen.", "Im unteren Teil des Ofens 35 Min backen."]},
{"n": "Spargelrisotto mit Zitrone", "von": 4, "bis": 6, "z": 40, "k": "v", "zu": [[500, "g", "Grüne Spargeln"], [240, "g", "Risottoreis"], [1, "", "Zwiebel"], [1, "dl", "Weisswein"], [1, "", "Zitrone, unbehandelt"], [60, "g", "Parmesan"]], "vo": ["Butter", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Holzige Spargelenden abschneiden, Spargeln in Stücke schneiden, Spitzen beiseitelegen.", "Zwiebel hacken und in Butter andünsten. Reis und Spargelstücke 2 Min mitdünsten.", "Mit Wein ablöschen, nach und nach heisse Bouillon zugeben und 18 Min rühren. Nach 12 Min die Spitzen zugeben.", "Zitronenschale abreiben, mit Parmesan und Butter unterrühren.", "Mit Zitronensaft, Salz und Pfeffer abschmecken."]},
{"n": "Spinat-Feta-Wähe", "von": 3, "bis": 5, "z": 55, "k": "v", "zu": [[1, "Packung", "Blätterteig, rund"], [500, "g", "Blattspinat"], [200, "g", "Feta"], [3, "", "Eier"], [1.5, "dl", "Halbrahm"], [3, "", "Frühlingszwiebeln"]], "vo": ["Olivenöl", "Knoblauch", "Salz", "Pfeffer", "Muskat"], "s": ["Ofen auf 200 °C vorheizen. Teig in eine Wähenform legen und einstechen.", "Frühlingszwiebeln und Knoblauch in Olivenöl andünsten, Spinat zugeben und zusammenfallen lassen. Gut abtropfen.", "Spinat auf dem Teig verteilen und Feta darüberbröseln.", "Eier mit Rahm verquirlen, mit Pfeffer und Muskat würzen und darübergiessen.", "Im unteren Teil des Ofens 30–35 Min backen."]},
{"n": "Spinat-Ricotta-Cannelloni", "von": 3, "bis": 5, "z": 60, "k": "v", "zu": [[250, "g", "Cannelloni"], [500, "g", "Blattspinat, frisch"], [250, "g", "Ricotta"], [1, "Dose", "Tomaten, gehackt (400 g)"], [1, "", "Zwiebel"], [125, "g", "Mozzarella"], [40, "g", "Parmesan"]], "vo": ["Olivenöl", "Knoblauch", "Salz", "Pfeffer", "Muskat", "Oregano"], "s": ["Ofen auf 200 °C vorheizen. Spinat kurz andünsten, ausdrücken und hacken.", "Spinat mit Ricotta und Parmesan mischen, mit Salz, Pfeffer und Muskat würzen.", "Zwiebel und Knoblauch in Olivenöl andünsten, Tomaten zugeben, mit Oregano 10 Min köcheln.", "Cannelloni mit der Spinatmasse füllen und in eine Form mit etwas Sauce legen.", "Restliche Sauce darübergiessen, Mozzarella darauf zupfen und 30 Min backen."]},
{"n": "Tabouleh mit Kichererbsen", "von": 6, "bis": 9, "z": 30, "k": "vg", "zu": [[150, "g", "Bulgur, fein"], [2, "Bund", "Peterli, glattblättrig"], [1, "Bund", "Minze"], [400, "g", "Tomaten"], [1, "", "Gurke"], [1, "Dose", "Kichererbsen"], [2, "", "Zitronen"], [4, "", "Frühlingszwiebeln"], [3, "", "Fladenbrote"]], "vo": ["Olivenöl", "Salz", "Pfeffer", "Kreuzkümmel", "Paprika"], "s": ["Bulgur mit heissem Wasser knapp bedecken und 15 Min quellen lassen.", "Peterli und Minze fein hacken, Tomaten und Gurke klein würfeln, Frühlingszwiebeln in Ringe schneiden.", "Kichererbsen abspülen und in Olivenöl mit Kreuzkümmel und Paprika knusprig braten.", "Bulgur mit Kräutern, Gemüse, Zitronensaft, Olivenöl und Salz mischen.", "Kichererbsen darüber verteilen und mit Fladenbrot servieren."]},
{"n": "Tagliata mit Rucola und Tomaten", "von": 6, "bis": 9, "z": 30, "k": "f", "zu": [[450, "g", "Rindsentrecôte"], [100, "g", "Rucola"], [250, "g", "Cherrytomaten"], [50, "g", "Parmesan"], [1, "", "Ciabatta"], [1, "", "Zitrone"]], "vo": ["Olivenöl", "Essig", "Salz", "Pfeffer", "Knoblauch"], "s": ["Fleisch 30 Min vor dem Braten aus dem Kühlschrank nehmen.", "Auf dem Grill oder in einer sehr heissen Pfanne je 3 Min pro Seite braten, 5 Min ruhen lassen.", "Rucola und halbierte Tomaten mit Olivenöl, Essig und Salz anmachen und auf Teller verteilen.", "Fleisch in dünne Tranchen schneiden, auf den Salat legen und mit Salz und Pfeffer würzen.", "Parmesan darüberhobeln, mit Zitrone beträufeln und mit geröstetem Ciabatta servieren."]},
{"n": "Teriyaki-Lachs mit Reis", "von": 1, "bis": 12, "z": 30, "k": "fi", "zu": [[450, "g", "Lachsfilet"], [240, "g", "Jasminreis"], [1, "", "Brokkoli"], [3, "", "Frühlingszwiebeln"], [1, "EL", "Sesam"]], "vo": ["Sojasauce", "Honig", "Essig", "Knoblauch", "Rapsöl"], "s": ["Reis nach Packungsangabe kochen.", "Sojasauce, Honig, Essig und gehackten Knoblauch verrühren.", "Brokkoli in Röschen teilen und 4 Min dämpfen.", "Lachs in Portionen im Öl auf beiden Seiten 3 Min braten, Sauce zugeben und dicklich einkochen.", "Mit Frühlingszwiebeln und Sesam bestreuen und mit Reis und Brokkoli servieren."]},
{"n": "Thai-Curry mit Poulet", "von": 1, "bis": 12, "z": 30, "k": "f", "zu": [[400, "g", "Pouletbrust"], [1, "Dose", "Kokosmilch"], [2, "EL", "Rote Currypaste"], [2, "", "Peperoni"], [150, "g", "Kefen oder Zuckerschoten"], [240, "g", "Jasminreis"], [0.5, "Bund", "Thai-Basilikum"], [2, "EL", "Fischsauce"]], "vo": ["Rapsöl", "Zucker", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Poulet in Streifen, Peperoni in Stücke schneiden.", "Currypaste im Öl kurz anrösten, Kokosmilch zugeben und aufkochen.", "Poulet und Gemüse zugeben und 8 Min köcheln.", "Mit Fischsauce und Zucker abschmecken, Basilikum darüber und mit Reis servieren."]},
{"n": "Thai-Fischcurry mit Süsskartoffeln", "von": 11, "bis": 3, "z": 35, "k": "fi", "zu": [[450, "g", "Weisses Fischfilet (z.B. Seelachs)"], [400, "g", "Süsskartoffeln"], [2, "EL", "Rote Currypaste"], [4, "dl", "Kokosmilch"], [150, "g", "Zuckerschoten oder Spinat"], [1, "", "Limette"], [240, "g", "Jasminreis"]], "vo": ["Rapsöl", "Sojasauce", "Zucker", "Salz"], "s": ["Reis nach Packungsangabe kochen.", "Süsskartoffeln schälen und würfeln.", "Currypaste in Öl kurz anrösten, Kokosmilch und Süsskartoffeln dazugeben und 12 Min köcheln.", "Fisch in Würfel schneiden, mit dem Gemüse ins Curry geben und 5 Min ziehen lassen.", "Mit Sojasauce, Zucker und Limettensaft abschmecken und mit dem Reis servieren."]},
{"n": "Thailändischer Rindfleischsalat", "von": 6, "bis": 9, "z": 30, "k": "f", "zu": [[400, "g", "Rindshuft"], [1, "", "Gurke"], [250, "g", "Cherrytomaten"], [1, "", "Zwiebel, rot"], [1, "Bund", "Koriander"], [0.5, "Bund", "Minze"], [2, "", "Limetten"], [2, "EL", "Fischsauce"], [240, "g", "Jasminreis"]], "vo": ["Rapsöl", "Zucker", "Chili", "Salz", "Pfeffer"], "s": ["Reis garen.", "Fleisch salzen und pfeffern, in einer sehr heissen Pfanne je 3 Min pro Seite braten und 5 Min ruhen lassen.", "Limettensaft, Fischsauce, Zucker und Chili zu einer Sauce verrühren.", "Gurke in Scheiben schneiden, Tomaten halbieren, Zwiebel in feine Ringe schneiden und mit den Kräutern mischen.", "Fleisch in dünne Streifen schneiden, mit Salat und Sauce mischen und mit Reis servieren."]},
{"n": "Tofu-Pfanne mit Erdnusssauce", "von": 9, "bis": 11, "z": 30, "k": "vg", "zu": [[400, "g", "Tofu, nature"], [1, "", "Brokkoli"], [2, "", "Rüebli"], [3, "EL", "Erdnussbutter"], [1, "", "Limette"], [240, "g", "Jasminreis"], [40, "g", "Erdnüsse, geröstet"]], "vo": ["Rapsöl", "Sojasauce", "Knoblauch", "Chili", "Zucker"], "s": ["Reis nach Packungsangabe kochen.", "Tofu in Würfel schneiden, mit Sojasauce marinieren und in Öl knusprig braten. Herausnehmen.", "Brokkoli in Röschen teilen, Rüebli in Stäbchen schneiden und mit Knoblauch im Wok 5 Min pfannenrühren.", "Erdnussbutter, Sojasauce, Limettensaft, Zucker, Chili und etwas Wasser glatt rühren.", "Tofu und Sauce zum Gemüse geben, kurz erhitzen und mit gehackten Erdnüssen und Reis servieren."]},
{"n": "Tomatensalat mit Burrata", "von": 7, "bis": 9, "z": 20, "k": "v", "zu": [[800, "g", "Tomaten, verschiedene Sorten"], [2, "", "Burrata"], [1, "Bund", "Basilikum"], [1, "", "Ciabatta"], [1, "", "Schalotte"]], "vo": ["Olivenöl", "Essig", "Salz", "Pfeffer"], "s": ["Tomaten in Scheiben und Schnitze schneiden, auf einer Platte auslegen.", "Schalotte fein hacken und mit Essig, Olivenöl, Salz und Pfeffer zu einer Sauce rühren.", "Sauce über die Tomaten träufeln und 10 Min ziehen lassen.", "Burrata in die Mitte legen, aufreissen und mit Basilikum belegen.", "Ciabatta in Scheiben kurz rösten und dazu servieren."]},
{"n": "Tomatenwähe", "von": 7, "bis": 9, "z": 60, "k": "v", "zu": [[1, "Packung", "Kuchenteig, rund"], [700, "g", "Tomaten"], [150, "g", "Gruyère, gerieben"], [2, "", "Eier"], [1.5, "dl", "Halbrahm"], [0.5, "Bund", "Basilikum"], [3, "EL", "Paniermehl"]], "vo": ["Salz", "Pfeffer", "Oregano", "Senf"], "s": ["Teig mit dem Papier in ein Wähenblech legen, Boden mit einer Gabel einstechen und dünn mit Senf bestreichen.", "Paniermehl und die Hälfte des Käses auf den Boden streuen.", "Tomaten in Scheiben schneiden und ziegelartig darauflegen.", "Eier, Halbrahm, restlichen Käse, Salz, Pfeffer und Oregano verrühren und darübergiessen.", "Auf der untersten Rille bei 220 °C 35 Min backen, mit Basilikum bestreuen."]},
{"n": "Trofie al Pesto mit Bohnen", "von": 6, "bis": 9, "z": 30, "k": "v", "zu": [[350, "g", "Trofie oder Linguine"], [300, "g", "Kartoffeln, festkochend"], [200, "g", "Grüne Bohnen"], [2, "Bund", "Basilikum"], [40, "g", "Pinienkerne"], [60, "g", "Parmesan"], [1, "dl", "Olivenöl"]], "vo": ["Knoblauch", "Salz", "Pfeffer"], "s": ["Basilikum, Pinienkerne, Knoblauch, Parmesan und Olivenöl zu einem Pesto pürieren, salzen.", "Kartoffeln in kleine Würfel schneiden, Bohnen halbieren.", "Kartoffeln in Salzwasser 5 Min kochen, dann Pasta und Bohnen dazugeben und mitkochen.", "Abgiessen, dabei etwas Kochwasser auffangen.", "Alles mit dem Pesto und wenig Kochwasser mischen und sofort servieren."]},
{"n": "Vermicelles", "von": 10, "bis": 12, "z": 25, "k": "v", "zu": [[500, "g", "Marronipüree, gesüsst"], [3, "EL", "Kirsch"], [2, "dl", "Rahm"], [6, "", "Meringues"], [100, "g", "Glacé, Vanille"]], "vo": ["Zucker"], "s": ["Marronipüree mit Kirsch glatt rühren und kühl stellen.", "Rahm mit wenig Zucker steif schlagen.", "Meringues grob zerbrechen und in Schalen verteilen, je eine Kugel Glacé daraufgeben.", "Marronimasse durch eine Vermicellespresse darüberdrücken.", "Mit Schlagrahm garnieren und sofort servieren."]},
{"n": "Vitello tonnato", "von": 6, "bis": 8, "z": 90, "k": "f", "zu": [[500, "g", "Kalbsnuss oder Kalbsunterspälte"], [1, "Dose", "Thunfisch in Öl"], [3, "EL", "Mayonnaise"], [2, "EL", "Kapern"], [1, "", "Zitrone"], [100, "g", "Rucola"], [1, "", "Ciabatta"]], "vo": ["Gemüsebouillon", "Salz", "Pfeffer", "Olivenöl"], "s": ["Kalbfleisch in leicht siedender Bouillon 50 Min ziehen lassen, im Sud auskühlen lassen.", "Thunfisch, Mayonnaise, die Hälfte der Kapern, Zitronensaft und etwas Sud fein pürieren, abschmecken.", "Fleisch in sehr dünne Scheiben schneiden und auf Teller verteilen.", "Thunfischsauce darübergeben und mit restlichen Kapern bestreuen.", "Mit Rucola, Olivenöl und Ciabatta servieren."]},
{"n": "Weisse Bohnen mit Wirz", "von": 11, "bis": 2, "z": 45, "k": "vg", "zu": [[2, "Dose", "Weisse Bohnen"], [400, "g", "Wirz"], [2, "", "Rüebli"], [1, "", "Zwiebel"], [1, "Dose", "Pelati"], [1, "", "Ruchbrot"]], "vo": ["Olivenöl", "Knoblauch", "Gemüsebouillon", "Oregano", "Chili", "Salz", "Pfeffer"], "s": ["Zwiebel, Knoblauch und Rüebli würfeln, Wirz in Streifen schneiden.", "Zwiebel, Knoblauch und Rüebli in Olivenöl andünsten.", "Wirz, Pelati und etwas Bouillon dazugeben, mit Oregano und Chili würzen und 20 Min köcheln.", "Abgespülte Bohnen dazugeben und 10 Min mitkochen, bis der Eintopf sämig ist.", "Mit Olivenöl beträufeln und mit geröstetem Brot servieren."]},
{"n": "Wildgeschnetzeltes mit Pilzen", "von": 9, "bis": 11, "z": 35, "k": "f", "zu": [[450, "g", "Hirsch, geschnetzelt"], [300, "g", "Pilze, gemischt"], [1, "", "Schalotte"], [1, "dl", "Rotwein"], [1.5, "dl", "Rahm"], [400, "g", "Spätzli, frisch"], [2, "", "Birnen"], [3, "EL", "Preiselbeeren"]], "vo": ["Rapsöl", "Butter", "Mehl", "Gemüsebouillon", "Zucker", "Salz", "Pfeffer"], "s": ["Birnen schälen, halbieren, entkernen und in Zuckerwasser 10 Min weich pochieren. Mit Preiselbeeren füllen.", "Fleisch mit wenig Mehl bestäuben und portionenweise sehr heiss kurz anbraten, herausnehmen und würzen.", "Pilze in Scheiben schneiden und mit der gehackten Schalotte in Butter anbraten.", "Mit Rotwein ablöschen, Rahm und etwas Bouillon dazugeben und sämig einkochen.", "Fleisch nur noch erwärmen, nicht mehr kochen. Spätzli in Butter braten und mit den Birnen servieren."]},
{"n": "Wildschweinragout mit Stock", "von": 9, "bis": 12, "z": 135, "k": "f", "zu": [[500, "g", "Wildschweinragout"], [3, "dl", "Rotwein"], [2, "", "Rüebli"], [1, "", "Zwiebel"], [3, "EL", "Preiselbeeren"], [800, "g", "Kartoffeln, mehligkochend"], [2, "dl", "Milch"], [200, "g", "Rosenkohl"]], "vo": ["Rapsöl", "Mehl", "Tomatenpüree", "Gemüsebouillon", "Gewürze (Lorbeer, Wacholder)", "Butter", "Muskat", "Salz", "Pfeffer"], "s": ["Fleisch salzen, mit Mehl bestäuben und in Öl kräftig anbraten. Zwiebel und Rüebli würfeln und mitbraten.", "Tomatenpüree kurz mitrösten, mit Rotwein und etwas Bouillon ablöschen, Gewürze dazugeben und zugedeckt 1.5 Std schmoren.", "Kartoffeln schälen, in Salzwasser weich kochen, mit heisser Milch und Butter zu Stock stampfen und mit Muskat würzen.", "Rosenkohl halbieren, 8 Min in Salzwasser garen und in Butter schwenken.", "Preiselbeeren unter das Ragout rühren, abschmecken und mit Kartoffelstock und Rosenkohl servieren."]},
{"n": "Wirzrouladen mit Hackfleisch", "von": 11, "bis": 2, "z": 75, "k": "f", "zu": [[1, "", "Wirz"], [400, "g", "Hackfleisch, gemischt"], [1, "", "Zwiebel"], [1, "", "Ei"], [1, "", "Brötli vom Vortag"], [2, "dl", "Rahm"], [600, "g", "Kartoffeln, mehligkochend"]], "vo": ["Rapsöl", "Senf", "Gemüsebouillon", "Paprika", "Salz", "Pfeffer", "Butter"], "s": ["Grosse Wirzblätter ablösen und 3 Min in Salzwasser blanchieren, dicke Rippen flach schneiden.", "Brötli einweichen und ausdrücken, mit Hackfleisch, gehackter Zwiebel, Ei, Senf und Gewürzen mischen.", "Füllung auf die Blätter verteilen, einrollen und mit Küchenschnur binden.", "Rouladen in Öl rundum anbraten, mit Bouillon und Rahm ablöschen und zugedeckt 35 Min schmoren.", "Kartoffeln kochen und mit Butter zu Stock stampfen, mit den Rouladen und der Sauce servieren."]},
{"n": "Zander mit Rosenkohl", "von": 10, "bis": 12, "z": 40, "k": "fi", "zu": [[450, "g", "Zanderfilet"], [400, "g", "Rosenkohl"], [600, "g", "Kartoffeln, festkochend"], [50, "g", "Speckwürfeli"], [1, "", "Zitrone"]], "vo": ["Butter", "Rapsöl", "Mehl", "Salz", "Pfeffer"], "s": ["Kartoffeln in Salzwasser 20 Min kochen und in Butter schwenken.", "Rosenkohl halbieren, 6 Min in Salzwasser garen und abtropfen lassen.", "Speck in einer Pfanne knusprig braten, Rosenkohl dazugeben und mitbraten.", "Zander würzen, auf der Hautseite leicht mehlen und in Öl 4 Min braten, wenden, Butter dazugeben und 1 Min fertig braten.", "Mit Zitronensaft beträufeln und mit Rosenkohl und Kartoffeln servieren."]},
{"n": "Zucchetti-Puffer mit Joghurtdip", "von": 6, "bis": 9, "z": 40, "k": "v", "zu": [[700, "g", "Zucchetti"], [2, "", "Eier"], [80, "g", "Feta"], [0.5, "Bund", "Dill"], [1, "", "Zitrone"], [300, "g", "Griechischer Joghurt"], [1, "", "Gurke"]], "vo": ["Mehl", "Salz", "Pfeffer", "Rapsöl", "Knoblauch"], "s": ["Zucchetti grob raffeln, salzen, 10 Min stehen lassen und gut ausdrücken.", "Mit Eiern, zerbröckeltem Feta, gehacktem Dill und Mehl zu einem Teig mischen.", "Portionenweise in heissem Öl beidseitig je 3 Min goldbraun braten.", "Joghurt mit geriebener Gurke, gepresstem Knoblauch, Zitronensaft und Salz verrühren.", "Puffer warm mit dem Dip und Zitronenschnitzen servieren."]},
{"n": "Zucchetti-Risotto mit Zitrone", "von": 6, "bis": 9, "z": 35, "k": "v", "zu": [[500, "g", "Zucchetti"], [240, "g", "Risottoreis"], [1, "", "Zwiebel"], [1, "dl", "Weisswein"], [60, "g", "Parmesan"], [1, "", "Zitrone, unbehandelt"], [0.5, "Bund", "Basilikum"]], "vo": ["Butter", "Olivenöl", "Gemüsebouillon", "Salz", "Pfeffer"], "s": ["Zucchetti klein würfeln, Zwiebel fein hacken.", "Zwiebel in Butter andünsten, Reis 2 Min mitdünsten und mit Wein ablöschen.", "Nach und nach heisse Bouillon dazugeben und 18 Min rühren.", "Zucchetti nach 10 Min dazugeben und mitgaren.", "Parmesan, Zitronenschale und etwas Saft unterrühren, mit Basilikum servieren."]},
{"n": "Zwetschgenwähe", "von": 8, "bis": 10, "z": 60, "k": "v", "zu": [[1, "Packung", "Kuchenteig, rund"], [800, "g", "Zwetschgen"], [40, "g", "Mandeln, gemahlen"], [2, "", "Eier"], [1.5, "dl", "Halbrahm"], [1, "dl", "Milch"]], "vo": ["Zucker", "Zimt", "Mehl"], "s": ["Ofen auf 220 °C vorheizen. Teig mit dem Backpapier ins Blech legen und einstechen.", "Mandeln auf dem Teig verteilen.", "Zwetschgen halbieren, entsteinen und dicht wie Ziegel auf den Teig legen.", "Eier, Halbrahm, Milch, Zucker und wenig Mehl verquirlen und darübergiessen.", "In der unteren Ofenhälfte 35 Min backen, mit Zimtzucker bestreuen und lauwarm servieren."]},
{"n": "Zürcher Geschnetzeltes mit Rösti", "von": 1, "bis": 12, "z": 45, "k": "f", "zu": [[450, "g", "Kalbfleisch, geschnetzelt"], [250, "g", "Champignons"], [1, "", "Zwiebel"], [1, "dl", "Weisswein"], [2, "dl", "Rahm"], [800, "g", "Kartoffeln, festkochend, vom Vortag gekocht"], [0.5, "Bund", "Peterli"]], "vo": ["Butter", "Rapsöl", "Mehl", "Salz", "Pfeffer", "Gemüsebouillon"], "s": ["Kartoffeln schälen, grob raffeln, salzen und in Butter zu einer Rösti formen, beidseitig je 12 Min goldbraun braten.", "Fleisch mit wenig Mehl bestäuben und portionenweise in heissem Öl kurz anbraten, herausnehmen.", "Zwiebel und geschnittene Champignons in Butter andünsten.", "Mit Wein ablöschen, Rahm und wenig Bouillon dazugeben und einkochen lassen.", "Fleisch wieder dazugeben, nur noch erhitzen, abschmecken und mit Peterli und Rösti servieren."]},
{"n": "Älplermagronen mit Apfelmus", "von": 1, "bis": 12, "z": 35, "k": "v", "zu": [[300, "g", "Hörnli"], [400, "g", "Kartoffeln, festkochend"], [2, "dl", "Rahm"], [150, "g", "Gruyère, gerieben"], [2, "", "Zwiebeln"], [1, "Glas", "Apfelmus"]], "vo": ["Butter", "Salz", "Pfeffer", "Muskat"], "s": ["Kartoffeln schälen und würfeln. Mit den Hörnli in Salzwasser al dente kochen, abgiessen.", "Zwiebeln in Ringe schneiden und in Butter langsam goldbraun braten.", "Rahm erhitzen, mit Pfeffer und Muskat würzen.", "Hörnli, Kartoffeln, Rahm und Käse mischen, bis der Käse schmilzt.", "Mit Röstzwiebeln belegen und mit Apfelmus servieren."]},
];
